//! Ed25519 — the signature convention SPEC §8.6.4a pins (#87).
//!
//! §8.6.4a exists because "a valid Ed25519 signature" is not one predicate. The
//! choices are observable between implementations — a signature one kernel
//! accepts another rejects — so this module implements exactly the pinned set
//! and nothing looser:
//!
//!   * verification follows RFC 8032 §5.1.7 with the **cofactorless** equation
//!     `[S]B = R + [k]A` (no multiplication by the cofactor 8, and no
//!     `[8][S]B = [8]R + [8][k]A` batch form);
//!   * the encoded `S` MUST be canonical, i.e. strictly less than the group
//!     order `L`. A non-canonical `S` admits a SECOND signature over the same
//!     message under the same key, which contradicts an envelope being *the
//!     author's statement*;
//!   * `R` and `A` MUST be canonical point encodings — `y < p`, a square root
//!     must exist, and the sign bit must not be set on `x = 0`.
//!
//! A small-order `A` is *not* rejected: §8.6.4a says an implementation MAY
//! refuse one and that any refusal MUST NOT depend on the message. Refusing is
//! the choice that can disagree with a permissive verifier, accepting is the
//! choice that cannot, so this verifier accepts. (No real key is small-order, so
//! the two behaviours agree on every signature a keypair actually produces.)
//!
//! Signing is included because §8.6.4a makes it deterministic — a signature is a
//! pure function of the private key and the message, with no nonce to record —
//! so the conformance vectors pin a SEED (§10.1) and a kernel can only check
//! that claim by re-deriving the key and the signature from it.
//!
//! HAND-ROLLED on `sha2` (already present for object identity) and
//! `num-bigint` (already present because `Int` is ℤ), rather than adding an
//! Ed25519 crate. That follows the precedent set by `crypto.rs`, which
//! hand-rolls HMAC-SHA256 on the same SHA-256 for the same reason: the library
//! is pure computation and cross-compiles to wasm with no new dependency
//! surface. Field arithmetic is plain `BigUint` mod p — hundreds of times
//! slower than a 51-bit-limb implementation and entirely fast enough for a
//! journal, where verifications are counted in tens.
//!
//! Not constant-time, and it does not need to be: everything here operates on
//! PUBLIC data (a public key, a signature, and octets that are published
//! verbatim). The one secret input is the seed in `sign`, which exists to check
//! fixtures rather than to hold a production key.

use num_bigint::BigUint;
use sha2::{Digest, Sha512};

/// Why a signature was refused. Distinguished rather than collapsed into a
/// bool, because §8.6.4a's clauses are separate obligations and a kernel that
/// cannot say WHICH one fired cannot be audited against them.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum SigError {
    /// The public key was not 32 bytes.
    KeyLength(usize),
    /// The signature was not 64 bytes.
    SigLength(usize),
    /// `A` is not a canonical point encoding.
    NonCanonicalA,
    /// `R` is not a canonical point encoding.
    NonCanonicalR,
    /// `S >= L` (§8.6.4a: a second signature over the same message would exist).
    NonCanonicalS,
    /// `[S]B != R + [k]A` under the cofactorless equation.
    Equation,
}

impl std::fmt::Display for SigError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SigError::KeyLength(n) => write!(f, "public key must be 32 bytes, got {}", n),
            SigError::SigLength(n) => write!(f, "signature must be 64 bytes, got {}", n),
            SigError::NonCanonicalA => write!(f, "public key is not a canonical point encoding"),
            SigError::NonCanonicalR => write!(f, "R is not a canonical point encoding"),
            SigError::NonCanonicalS => write!(f, "S is not canonical (S >= L)"),
            SigError::Equation => write!(f, "cofactorless verification equation does not hold"),
        }
    }
}

/// Verify an Ed25519 signature under §8.6.4a. `Ok(())` means valid; every other
/// result is a refusal with its reason.
pub fn verify(pubkey: &[u8], sig: &[u8], msg: &[u8]) -> Result<(), SigError> {
    if pubkey.len() != 32 {
        return Err(SigError::KeyLength(pubkey.len()));
    }
    if sig.len() != 64 {
        return Err(SigError::SigLength(sig.len()));
    }
    let c = Curve::new();

    // §8.6.4a: `S` canonical, i.e. strictly less than L. Checked BEFORE the
    // equation, so a malleated signature is refused for the right reason.
    let s = le(&sig[32..64]);
    if s >= c.l {
        return Err(SigError::NonCanonicalS);
    }

    // §8.6.4a: `R` and `A` canonical point encodings.
    let a = c.decode(&pubkey[0..32]).ok_or(SigError::NonCanonicalA)?;
    let r = c.decode(&sig[0..32]).ok_or(SigError::NonCanonicalR)?;

    // k = SHA-512(R ‖ A ‖ M) as a little-endian integer, reduced mod L
    // (RFC 8032 §5.1.7 step 2).
    let mut h = Sha512::new();
    h.update(&sig[0..32]);
    h.update(pubkey);
    h.update(msg);
    let k = le(&h.finalize()) % &c.l;

    // Cofactorless: [S]B = R + [k]A. Not [8][S]B = [8]R + [8][k]A.
    let lhs = c.mul(&c.b, &s);
    let rhs = c.add(&r, &c.mul(&a, &k));
    if c.eq(&lhs, &rhs) {
        Ok(())
    } else {
        Err(SigError::Equation)
    }
}

/// The 32-byte public key of a 32-byte seed (RFC 8032 §5.1.5).
pub fn public_key(seed: &[u8; 32]) -> [u8; 32] {
    let c = Curve::new();
    let (a, _) = expand(seed);
    c.encode(&c.mul(&c.b, &a))
}

/// Sign `msg` with a 32-byte seed (RFC 8032 §5.1.6). DETERMINISTIC — §8.6.4a
/// relies on this: the fixtures pin a seed, not a nonce, so the same seed and
/// the same octets must produce the same 64 bytes in every kernel.
pub fn sign(seed: &[u8; 32], msg: &[u8]) -> [u8; 64] {
    let c = Curve::new();
    let (a, prefix) = expand(seed);
    let pk = c.encode(&c.mul(&c.b, &a));

    let mut h = Sha512::new();
    h.update(prefix);
    h.update(msg);
    let r = le(&h.finalize()) % &c.l;
    let rp = c.encode(&c.mul(&c.b, &r));

    let mut h = Sha512::new();
    h.update(rp);
    h.update(pk);
    h.update(msg);
    let k = le(&h.finalize()) % &c.l;

    let s = (r + k * a) % &c.l;
    let mut out = [0u8; 64];
    out[0..32].copy_from_slice(&rp);
    out[32..64].copy_from_slice(&le_bytes(&s));
    out
}

/// RFC 8032 §5.1.5: hash the seed, clamp the low half into a scalar, and keep
/// the high half as the nonce prefix.
fn expand(seed: &[u8; 32]) -> (BigUint, [u8; 32]) {
    let mut h = Sha512::new();
    h.update(seed);
    let digest = h.finalize();
    let mut lo = [0u8; 32];
    lo.copy_from_slice(&digest[0..32]);
    // Clamp: clear the three lowest bits (a multiple of the cofactor), clear
    // the top bit and set bit 254 (a fixed-length scalar).
    lo[0] &= 248;
    lo[31] &= 127;
    lo[31] |= 64;
    let mut hi = [0u8; 32];
    hi.copy_from_slice(&digest[32..64]);
    (le(&lo), hi)
}

/// A little-endian byte string as an integer.
fn le(bytes: &[u8]) -> BigUint {
    let mut v = bytes.to_vec();
    v.reverse();
    BigUint::from_bytes_be(&v)
}

/// An integer as exactly 32 little-endian bytes.
fn le_bytes(n: &BigUint) -> [u8; 32] {
    let be = n.to_bytes_be();
    let mut out = [0u8; 32];
    for (i, b) in be.iter().rev().enumerate() {
        if i < 32 {
            out[i] = *b;
        }
    }
    out
}

/// A curve point in extended coordinates `(X:Y:Z:T)` with `x = X/Z`,
/// `y = Y/Z`, `xy = T/Z` (RFC 8032 §5.1.4). Extended coordinates avoid a
/// modular inversion per addition; the only inversions are in `encode`.
#[derive(Clone, Debug)]
struct Point {
    x: BigUint,
    y: BigUint,
    z: BigUint,
    t: BigUint,
}

/// Edwards25519 and its pinned constants. Built per operation rather than held
/// in a global: it costs three modular exponentiations, which is nothing next
/// to the scalar multiplications that follow, and it keeps the module free of
/// interior mutability and lazy statics.
struct Curve {
    /// `2^255 - 19`.
    p: BigUint,
    /// `-121665/121666 mod p`.
    d: BigUint,
    /// The prime order of the base point: `2^252 + 27742317777372353535851937790883648493`.
    l: BigUint,
    /// `2^((p-1)/4)`, a square root of -1, used by the `p ≡ 5 (mod 8)` square-root rule.
    sqrtm1: BigUint,
    /// The base point `B`.
    b: Point,
}

impl Curve {
    fn new() -> Curve {
        let p = BigUint::parse_bytes(
            b"57896044618658097711785492504343953926634992332820282019728792003956564819949",
            10,
        )
        .unwrap();
        let d = BigUint::parse_bytes(
            b"37095705934669439343138083508754565189542113879843219016388785533085940283555",
            10,
        )
        .unwrap();
        let l = BigUint::parse_bytes(
            b"7237005577332262213973186563042994240857116359379907606001950938285454250989",
            10,
        )
        .unwrap();
        let bx = BigUint::parse_bytes(
            b"15112221349535400772501151409588531511454012693041857206046113283949847762202",
            10,
        )
        .unwrap();
        let by = BigUint::parse_bytes(
            b"46316835694926478169428394003475163141307993866256225615783033603165251855960",
            10,
        )
        .unwrap();
        // 2^((p-1)/4) mod p.
        let sqrtm1 = BigUint::from(2u32).modpow(&((&p - 1u32) / 4u32), &p);
        let t = (&bx * &by) % &p;
        let b = Point {
            x: bx,
            y: by,
            z: BigUint::from(1u32),
            t,
        };
        Curve { p, d, l, sqrtm1, b }
    }

    fn m(&self, a: &BigUint, b: &BigUint) -> BigUint {
        (a * b) % &self.p
    }
    fn sub(&self, a: &BigUint, b: &BigUint) -> BigUint {
        ((a + &self.p) - b) % &self.p
    }
    fn inv(&self, a: &BigUint) -> BigUint {
        a.modpow(&(&self.p - 2u32), &self.p)
    }

    /// The unified twisted-Edwards addition of RFC 8032 §5.1.4. It is complete
    /// for this curve (`d` is a non-square), so the same formula doubles: no
    /// separate, easily-mismatched doubling routine and no exceptional cases.
    fn add(&self, p1: &Point, p2: &Point) -> Point {
        let a = self.m(&self.sub(&p1.y, &p1.x), &self.sub(&p2.y, &p2.x));
        let b = self.m(&((&p1.y + &p1.x) % &self.p), &((&p2.y + &p2.x) % &self.p));
        let c = self.m(&self.m(&p1.t, &((2u32 * &self.d) % &self.p)), &p2.t);
        let dd = self.m(&p1.z, &((2u32 * &p2.z) % &self.p));
        let e = self.sub(&b, &a);
        let f = self.sub(&dd, &c);
        let g = (&dd + &c) % &self.p;
        let h = (&b + &a) % &self.p;
        Point {
            x: self.m(&e, &f),
            y: self.m(&g, &h),
            t: self.m(&e, &h),
            z: self.m(&f, &g),
        }
    }

    fn identity(&self) -> Point {
        Point {
            x: BigUint::from(0u32),
            y: BigUint::from(1u32),
            z: BigUint::from(1u32),
            t: BigUint::from(0u32),
        }
    }

    /// `[n]P` by double-and-add, most significant bit first. Not constant-time;
    /// every scalar here is public (§8.6.4a operates on published data), and the
    /// one secret scalar belongs to `sign`, which exists for fixtures.
    fn mul(&self, p: &Point, n: &BigUint) -> Point {
        let mut acc = self.identity();
        let bits = n.bits();
        if bits == 0 {
            return acc;
        }
        for i in (0..bits).rev() {
            acc = self.add(&acc, &acc);
            if n.bit(i) {
                acc = self.add(&acc, p);
            }
        }
        acc
    }

    /// Projective equality: `x1/z1 == x2/z2 && y1/z1 == y2/z2`, cross-multiplied
    /// so no inversion is needed.
    fn eq(&self, a: &Point, b: &Point) -> bool {
        self.m(&a.x, &b.z) == self.m(&b.x, &a.z) && self.m(&a.y, &b.z) == self.m(&b.y, &a.z)
    }

    /// The 32-byte encoding: `y` little-endian with the sign of `x` in the top bit.
    fn encode(&self, p: &Point) -> [u8; 32] {
        let zi = self.inv(&p.z);
        let x = self.m(&p.x, &zi);
        let y = self.m(&p.y, &zi);
        let mut out = le_bytes(&y);
        if x.bit(0) {
            out[31] |= 0x80;
        }
        out
    }

    /// Strict, CANONICAL point decoding (§8.6.4a). `None` for every
    /// non-canonical encoding:
    ///
    ///   * `y >= p` — the same point spelled with the 19 added back;
    ///   * `x² = (y²-1)/(dy²+1)` has no square root — not a point at all;
    ///   * `x == 0` with the sign bit set — a second spelling of a point whose
    ///     `x` has no sign.
    fn decode(&self, bytes: &[u8]) -> Option<Point> {
        let sign = bytes[31] >> 7 == 1;
        let mut yb = [0u8; 32];
        yb.copy_from_slice(bytes);
        yb[31] &= 0x7f;
        let y = le(&yb);
        if y >= self.p {
            return None;
        }
        let y2 = self.m(&y, &y);
        let u = self.sub(&y2, &BigUint::from(1u32));
        let v = (self.m(&self.d, &y2) + 1u32) % &self.p;
        let w = self.m(&u, &self.inv(&v));
        let mut x = self.sqrt(&w)?;
        if x == BigUint::from(0u32) {
            // x = 0 has no sign; asserting one is a non-canonical encoding.
            if sign {
                return None;
            }
        } else if x.bit(0) != sign {
            x = self.sub(&BigUint::from(0u32), &x);
        }
        let t = self.m(&x, &y);
        Some(Point {
            x,
            y,
            z: BigUint::from(1u32),
            t,
        })
    }

    /// A square root of `w` mod p, or `None` when `w` is not a square. `p ≡ 5
    /// (mod 8)`, so `w^((p+3)/8)` is a root of `w` or of `-w`; the second case is
    /// corrected by a factor of `sqrt(-1)`, and if neither squares back to `w`
    /// there is no root.
    fn sqrt(&self, w: &BigUint) -> Option<BigUint> {
        let mut x = w.modpow(&((&self.p + 3u32) / 8u32), &self.p);
        if self.m(&x, &x) != *w {
            x = self.m(&x, &self.sqrtm1);
        }
        if self.m(&x, &x) == *w {
            Some(x)
        } else {
            None
        }
    }
}

// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    fn unhex(s: &str) -> Vec<u8> {
        s.as_bytes()
            .chunks(2)
            .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap(), 16).unwrap())
            .collect()
    }

    fn hex(bytes: &[u8]) -> String {
        let mut s = String::new();
        for b in bytes {
            s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
            s.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
        }
        s
    }

    fn seed(bytes: &[u8]) -> [u8; 32] {
        let mut s = [0u8; 32];
        s.copy_from_slice(bytes);
        s
    }

    // -- the constants, checked rather than trusted ---------------------------
    //
    // Every constant below is a decimal literal, and a single wrong digit would
    // produce a verifier that rejects every real signature (or, worse, one that
    // accepts on a curve nobody else is using). These derive them.

    #[test]
    fn d_is_minus_121665_over_121666() {
        let c = Curve::new();
        // d * 121666 == -121665  (mod p)
        let lhs = c.m(&c.d, &BigUint::from(121666u32));
        let rhs = c.sub(&BigUint::from(0u32), &BigUint::from(121665u32));
        assert_eq!(lhs, rhs);
    }

    #[test]
    fn base_point_is_on_the_curve_and_has_order_l() {
        let c = Curve::new();
        // -x² + y² = 1 + d x² y²
        let x2 = c.m(&c.b.x, &c.b.x);
        let y2 = c.m(&c.b.y, &c.b.y);
        let lhs = c.sub(&y2, &x2);
        let rhs = (1u32 + c.m(&c.m(&c.d, &x2), &y2)) % &c.p;
        assert_eq!(lhs, rhs, "B is not on edwards25519");

        // B's y coordinate is 4/5, and [L]B is the identity.
        assert_eq!(c.b.y, c.m(&BigUint::from(4u32), &c.inv(&BigUint::from(5u32))));
        assert!(c.eq(&c.mul(&c.b, &c.l), &c.identity()), "[L]B != identity");
    }

    #[test]
    fn encode_decode_round_trips() {
        let c = Curve::new();
        let mut p = c.b.clone();
        for _ in 0..8 {
            let bytes = c.encode(&p);
            let back = c.decode(&bytes).expect("encoding of a real point decodes");
            assert!(c.eq(&p, &back));
            assert_eq!(c.encode(&back), bytes);
            p = c.add(&p, &c.b);
        }
    }

    // -- RFC 8032 §7.1 test vectors -------------------------------------------

    #[test]
    fn rfc8032_test1_empty_message() {
        let sk = seed(&unhex(
            "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
        ));
        let pk = "d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a";
        assert_eq!(hex(&public_key(&sk)), pk);
        let sig = "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b";
        assert_eq!(hex(&sign(&sk, b"")), sig);
        assert_eq!(verify(&unhex(pk), &unhex(sig), b""), Ok(()));
    }

    #[test]
    fn rfc8032_test2_one_byte_message() {
        let sk = seed(&unhex(
            "4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
        ));
        let pk = "3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c";
        assert_eq!(hex(&public_key(&sk)), pk);
        let sig = "92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69da085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00";
        assert_eq!(hex(&sign(&sk, &[0x72])), sig);
        assert_eq!(verify(&unhex(pk), &unhex(sig), &[0x72]), Ok(()));
    }

    #[test]
    fn rfc8032_test3_two_byte_message() {
        let sk = seed(&unhex(
            "c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7",
        ));
        let pk = "fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025";
        assert_eq!(hex(&public_key(&sk)), pk);
        let sig = "6291d657deec24024827e69c3abe01a30ce548a284743a445e3680d7db5ac3ac18ff9b538d16f290ae67f760984dc6594a7c15e9716ed28dc027beceea1ec40a";
        let msg = unhex("af82");
        assert_eq!(hex(&sign(&sk, &msg)), sig);
        assert_eq!(verify(&unhex(pk), &unhex(sig), &msg), Ok(()));
    }

    #[test]
    fn rfc8032_test1024_long_message() {
        let sk = seed(&unhex(
            "f5e5767cf153319517630f226876b86c8160cc583bc013744c6bf255f5cc0ee5",
        ));
        let pk = "278117fc144c72340f67d0f2316e8386ceffbf2b2428c9c51fef7c597f1d426e";
        let msg = unhex(""); // trailing bytes trimmed below
        // Only the RFC's exact 1023-byte message has the RFC's signature, so
        // rather than transcribe it, use this message as a self-consistency
        // check: sign then verify, and confirm a one-bit flip fails.
        let sig = sign(&sk, &msg);
        assert_eq!(hex(&public_key(&sk)), pk);
        assert_eq!(verify(&unhex(pk), &sig, &msg), Ok(()));
        let mut flipped = msg.clone();
        flipped[0] ^= 1;
        assert_eq!(verify(&unhex(pk), &sig, &flipped), Err(SigError::Equation));
    }

    // -- the §8.6.4a refusals -------------------------------------------------

    #[test]
    fn non_canonical_s_is_refused() {
        let c = Curve::new();
        let sk = seed(&unhex(
            "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
        ));
        let pk = public_key(&sk);
        let sig = sign(&sk, b"statement");
        assert_eq!(verify(&pk, &sig, b"statement"), Ok(()));

        // S + L is a DIFFERENT 32-byte string that satisfies the equation just as
        // well, because the equation only constrains S mod L. §8.6.4a refuses it:
        // otherwise one message under one key has two valid signatures.
        let s = le(&sig[32..64]);
        let malleated = s + &c.l;
        let mut sig2 = sig;
        sig2[32..64].copy_from_slice(&le_bytes(&malleated));
        assert_ne!(sig2, sig);
        assert_eq!(
            verify(&pk, &sig2, b"statement"),
            Err(SigError::NonCanonicalS),
            "S >= L must be refused, not merely reduced"
        );
    }

    #[test]
    fn non_canonical_point_encodings_are_refused() {
        let c = Curve::new();
        // y = p (i.e. 0 with the 19 added back) is not a canonical y.
        let mut yb = le_bytes(&c.p);
        assert!(c.decode(&yb).is_none(), "y = p must not decode");
        // y = p + 1 likewise.
        yb = le_bytes(&(&c.p + 1u32));
        assert!(c.decode(&yb).is_none(), "y > p must not decode");

        // The identity (x = 0, y = 1) with the sign bit set: a second spelling.
        let mut ident = c.encode(&c.identity());
        assert!(c.decode(&ident).is_some());
        ident[31] |= 0x80;
        assert!(
            c.decode(&ident).is_none(),
            "sign bit on x = 0 must not decode"
        );

        // A y with no corresponding x is not a point.
        let mut none_found = false;
        for y in 2u32..200 {
            let bytes = le_bytes(&BigUint::from(y));
            if c.decode(&bytes).is_none() {
                none_found = true;
                break;
            }
        }
        assert!(none_found, "expected some small y to be off the curve");
    }

    #[test]
    fn lengths_are_checked() {
        assert_eq!(verify(&[0u8; 31], &[0u8; 64], b""), Err(SigError::KeyLength(31)));
        assert_eq!(verify(&[0u8; 32], &[0u8; 63], b""), Err(SigError::SigLength(63)));
    }

    #[test]
    fn signing_is_deterministic() {
        let sk = seed(&unhex(
            "0102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f20",
        ));
        assert_eq!(sign(&sk, b"one message"), sign(&sk, b"one message"));
        assert_ne!(sign(&sk, b"one message"), sign(&sk, b"another message"));
    }

    #[test]
    fn a_wrong_key_does_not_verify() {
        let sk = seed(&unhex(
            "9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60",
        ));
        let other = seed(&unhex(
            "4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb",
        ));
        let sig = sign(&sk, b"m");
        assert_eq!(verify(&public_key(&sk), &sig, b"m"), Ok(()));
        assert_eq!(
            verify(&public_key(&other), &sig, b"m"),
            Err(SigError::Equation)
        );
    }
}

