//! The journal: canonical entry encoding, strict reading, publication identity
//! and the name revision (SPEC §8, §8.2, §8.2.1, §8.2.2, §8.4, §8.6.2, #87).
//!
//! Everything here is BYTE-SIGNIFICANT. §8.2.1 makes the member order normative
//! rather than a formatting preference, and the reason is mechanical: `chain`
//! (§8) and the entry signature (§8.4) are both computed over "the entry's
//! compact JSON", and §8.2.2 makes the SHA-256 of that same line the identity of
//! a publication. Two implementations ordering members differently therefore
//! compute different chains, different signatures and different publication
//! identities for one logical entry, and each rejects the other's journal
//! wholesale. There is no error message for this; it presents as a journal that
//! simply will not verify anywhere else.
//!
//! For the same reason reading is STRICT (§8.2.1): parse the line, re-encode it
//! canonically, and refuse the journal unless the result is byte-identical. A
//! lenient reader would accept several spellings of one entry, which — since
//! chains and signatures are over these bytes — means accepting several
//! identities for one entry. It follows that nothing here ever normalizes a
//! non-canonical line and then verifies the normalized form: that would verify a
//! statement other than the one the journal contains.
//!
//! Metadata only (§9): none of this reaches definition identity.

use crate::hash::{sha256, sha256_hex};
use num_bigint::BigUint;

/// A journal entry (§8), in the §8.2.1 member order.
///
/// Every member is a `String` (`seq` aside) and EMPTY MEANS ABSENT, which is how
/// §8.2.1 states the omission rule. Keeping the raw member text rather than a
/// richer type is deliberate: strict reading has to round-trip the exact bytes,
/// and a type that normalized anything on the way in would make the round-trip
/// check compare a normalization against itself.
///
/// The DECLARATION ORDER of these fields is the normative encoding order of
/// §8.2.1 and is not free to change.
#[derive(Clone, Debug, Default, PartialEq, Eq)]
pub struct Entry {
    /// One plus the number of existing newline-terminated records (§8.2).
    pub seq: u64,
    /// RFC3339 UTC, no subsecond field (§8.2).
    pub time: String,
    /// Principal string, self-reported in local mode (§8).
    pub author: String,
    /// Kernel version string (§8).
    pub verifier: String,
    pub name: String,
    /// `data` | `func` | `prove` | `cross` … (§8).
    pub kind: String,
    /// `accepted` | `falsified` | `rejected` | `blocked` | `pending` (§8).
    pub status: String,
    /// The stored object hash; absent on a gate rejection (§8.2).
    pub hash: String,
    /// The hash the name pointed at BEFORE this entry — always, including when
    /// it already pointed at the same hash; omitted only when the name did not
    /// previously exist (§8.2, as amended).
    pub prev: String,
    pub error: String,
    pub guarantee: String,
    pub termination: String,
    /// Author-supplied context-slice hash (§8).
    pub context: String,
    /// Entry-signature key, lowercase hex of 32 bytes (§8.4).
    pub pubkey: String,
    /// Entry signature, lowercase hex of 64 bytes (§8.4).
    pub sig: String,
    /// The exact envelope octets, canonical base64 (§8.6.3).
    pub envelope_b64: String,
    /// Lowercase hex of the key that signed the envelope octets (§8.6.3).
    pub author_pubkey: String,
    /// Lowercase hex of the 64-byte signature over the DECODED octets (§8.6.3).
    pub author_sig: String,
    /// `applied` | `unchanged` | `none` (§8.6.3). Absent on legacy entries.
    pub name_transition: String,
    /// `SHA-256(anchor + "\n" + entry-bytes)`, lowercase hex (§8).
    pub chain: String,
}

/// The §8.2.1 member order, paired with a projection out of [`Entry`].
///
/// One table rather than a hand-written sequence of `push` calls, so the
/// encoder, the strict reader's key validation and the order check all read the
/// SAME list. A normative order duplicated in three places is an order that
/// drifts.
const MEMBERS: &[(&str, Member)] = &[
    ("seq", Member::Seq),
    ("time", Member::Str(|e| &e.time)),
    ("author", Member::Str(|e| &e.author)),
    ("verifier", Member::Str(|e| &e.verifier)),
    ("name", Member::Str(|e| &e.name)),
    ("kind", Member::Str(|e| &e.kind)),
    ("status", Member::Str(|e| &e.status)),
    ("hash", Member::Str(|e| &e.hash)),
    ("prev", Member::Str(|e| &e.prev)),
    ("error", Member::Str(|e| &e.error)),
    ("guarantee", Member::Str(|e| &e.guarantee)),
    ("termination", Member::Str(|e| &e.termination)),
    ("context", Member::Str(|e| &e.context)),
    ("pubkey", Member::Str(|e| &e.pubkey)),
    ("sig", Member::Str(|e| &e.sig)),
    ("envelope_b64", Member::Str(|e| &e.envelope_b64)),
    ("author_pubkey", Member::Str(|e| &e.author_pubkey)),
    ("author_sig", Member::Str(|e| &e.author_sig)),
    ("name_transition", Member::Str(|e| &e.name_transition)),
    ("chain", Member::Str(|e| &e.chain)),
];

enum Member {
    Seq,
    Str(fn(&Entry) -> &String),
}

/// The members §8.2.1 says are ALWAYS present, even when empty (or zero).
///
/// §8.2.1's own sentence reads "except `seq`, `time`, `author`, `name`, and
/// `status`". `verifier` is here as well because the conformance vectors
/// (§10.1, `fixtures/envelope/vectors.jsonl`) carry a canonical entry line whose
/// `verifier` is present and empty — and those bytes are the interoperability
/// target, so following the prose against the fixture would fork every chain and
/// every entry signature involving an entry with no verifier. Recorded as a
/// divergence: §8.2.1's list appears to be missing one word.
const ALWAYS_PRESENT: &[&str] = &["seq", "time", "author", "verifier", "name", "status"];

fn always_present(key: &str) -> bool {
    ALWAYS_PRESENT.contains(&key)
}

/// The canonical compact-JSON encoding of an entry (§8.2.1).
///
/// Members in the normative order; empty (or zero, for `seq`) members omitted
/// except those §8.2.1 pins as always present. No whitespace anywhere, and no
/// trailing newline — the LF is the journal's record separator (§8.1), not part
/// of the entry.
pub fn encode(e: &Entry) -> String {
    let mut out = String::from("{");
    let mut first = true;
    for (key, member) in MEMBERS {
        let rendered = match member {
            Member::Seq => {
                if e.seq == 0 && !always_present(key) {
                    None
                } else {
                    Some(e.seq.to_string())
                }
            }
            Member::Str(get) => {
                let v = get(e);
                if v.is_empty() && !always_present(key) {
                    None
                } else {
                    Some(json_string(v))
                }
            }
        };
        if let Some(value) = rendered {
            if !first {
                out.push(',');
            }
            first = false;
            out.push('"');
            out.push_str(key);
            out.push_str("\":");
            out.push_str(&value);
        }
    }
    out.push('}');
    out
}

/// A JSON string literal, escaping the MINIMUM RFC 8259 requires: `"` and `\`,
/// and the control characters below `0x20` (the five short forms where they
/// exist, `\u00XX` otherwise). Everything else — including `<`, `>`, `&`,
/// `U+2028` and every other non-ASCII scalar — is emitted as literal UTF-8.
///
/// §8.2.1 does not pin this, and it is byte-significant: several widely-used
/// JSON encoders escape `<`, `>`, `&` and the line separators BY DEFAULT, and an
/// entry whose `error` message contains a `<` would then be two different lines,
/// two different chains and two different publication identities in two
/// conforming kernels. Minimal escaping is the choice here because it is the
/// one a reader can derive from RFC 8259 alone. See DIVERGENCES.md.
fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{8}' => out.push_str("\\b"),
            '\u{c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                out.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// Strict reading (§8.2.1): parse one journal line, then require that
/// re-encoding it canonically reproduces the input byte-for-byte.
///
/// Errors are returned for an unknown member, a duplicated member, a reordered
/// member, whitespace, trailing content after the object, a wrong member type,
/// and finally for any residual byte difference. The last check is what makes
/// the earlier ones a courtesy rather than the guarantee: whatever a lenient
/// parser might have silently accepted, the bytes have to come back identical.
pub fn parse(line: &str) -> Result<Entry, String> {
    let mut r = Reader {
        b: line.as_bytes(),
        i: 0,
    };
    let mut e = Entry::default();
    let mut seen: Vec<&'static str> = Vec::new();

    r.expect(b'{')?;
    if r.peek() == Some(b'}') {
        return Err("entry has no members; `seq`, `time`, `author`, `verifier`, `name` and `status` are always present".into());
    }
    loop {
        let key = r.string()?;
        let pos = MEMBERS
            .iter()
            .position(|(k, _)| *k == key)
            .ok_or_else(|| format!("unknown member {:?}", key))?;
        let (name, member) = &MEMBERS[pos];
        if seen.contains(name) {
            return Err(format!("duplicated member {:?}", name));
        }
        // Reordering: the members must appear in the §8.2.1 order, so each key's
        // index must exceed every index already seen.
        if let Some(last) = seen.last() {
            let last_pos = MEMBERS.iter().position(|(k, _)| k == last).unwrap();
            if pos < last_pos {
                return Err(format!(
                    "member {:?} appears after {:?}; §8.2.1 fixes the order",
                    name, last
                ));
            }
        }
        seen.push(name);
        r.expect(b':')?;
        match member {
            Member::Seq => e.seq = r.number()?,
            Member::Str(_) => {
                let v = r.string()?;
                assign(&mut e, name, v);
            }
        }
        match r.next() {
            Some(b',') => continue,
            Some(b'}') => break,
            Some(c) => return Err(format!("expected ',' or '}}', got {:?}", c as char)),
            None => return Err("truncated entry".into()),
        }
    }
    if r.i != r.b.len() {
        return Err(format!("trailing content after the entry object at byte {}", r.i));
    }
    for key in ALWAYS_PRESENT {
        if !seen.contains(key) {
            return Err(format!("member {:?} is always present (§8.2.1)", key));
        }
    }
    // §8.6.3 closes the value set for `name_transition`; an unrecognized value
    // is not a transition this version can interpret.
    if !e.name_transition.is_empty() && Transition::parse(&e.name_transition).is_none() {
        return Err(format!(
            "name_transition must be applied|unchanged|none, got {:?}",
            e.name_transition
        ));
    }
    let round_trip = encode(&e);
    if round_trip != line {
        return Err(format!(
            "entry is not canonical: re-encoding gives {:?}, stored line is {:?}",
            round_trip, line
        ));
    }
    Ok(e)
}

/// Assign a parsed string to the member `key` names. Written as a `match` rather
/// than a setter table because a `fn(&mut Entry) -> &mut String` table would let
/// `MEMBERS` be used for writing as well as reading, and only the READ order is
/// normative.
fn assign(e: &mut Entry, key: &str, v: String) {
    match key {
        "time" => e.time = v,
        "author" => e.author = v,
        "verifier" => e.verifier = v,
        "name" => e.name = v,
        "kind" => e.kind = v,
        "status" => e.status = v,
        "hash" => e.hash = v,
        "prev" => e.prev = v,
        "error" => e.error = v,
        "guarantee" => e.guarantee = v,
        "termination" => e.termination = v,
        "context" => e.context = v,
        "pubkey" => e.pubkey = v,
        "sig" => e.sig = v,
        "envelope_b64" => e.envelope_b64 = v,
        "author_pubkey" => e.author_pubkey = v,
        "author_sig" => e.author_sig = v,
        "name_transition" => e.name_transition = v,
        "chain" => e.chain = v,
        other => unreachable!("member {} has no string field", other),
    }
}

/// A strict compact-JSON reader for one entry object.
///
/// It accepts NO whitespace at all: §8.2.1 says added whitespace is an error,
/// and the canonical form has none, so tolerating it here and catching it later
/// in the byte comparison would only produce a worse error message.
struct Reader<'a> {
    b: &'a [u8],
    i: usize,
}

impl<'a> Reader<'a> {
    fn peek(&self) -> Option<u8> {
        self.b.get(self.i).copied()
    }
    fn next(&mut self) -> Option<u8> {
        let c = self.peek();
        if c.is_some() {
            self.i += 1;
        }
        c
    }
    fn expect(&mut self, c: u8) -> Result<(), String> {
        match self.next() {
            Some(g) if g == c => Ok(()),
            Some(g) => Err(format!(
                "expected {:?} at byte {}, got {:?}",
                c as char,
                self.i - 1,
                g as char
            )),
            None => Err(format!("expected {:?}, got end of line", c as char)),
        }
    }
    /// A JSON string. Escapes are decoded so the VALUE can be compared; the
    /// round-trip check in [`parse`] then rejects any spelling the canonical
    /// encoder would not have produced (`A` for `A`, say).
    fn string(&mut self) -> Result<String, String> {
        self.expect(b'"')?;
        let mut out = String::new();
        loop {
            let c = self.next().ok_or("unterminated string")?;
            match c {
                b'"' => return Ok(out),
                b'\\' => {
                    let e = self.next().ok_or("truncated escape")?;
                    match e {
                        b'"' => out.push('"'),
                        b'\\' => out.push('\\'),
                        b'/' => out.push('/'),
                        b'b' => out.push('\u{8}'),
                        b'f' => out.push('\u{c}'),
                        b'n' => out.push('\n'),
                        b'r' => out.push('\r'),
                        b't' => out.push('\t'),
                        b'u' => {
                            let h = self
                                .b
                                .get(self.i..self.i + 4)
                                .ok_or("truncated \\u escape")?;
                            let h = std::str::from_utf8(h).map_err(|e| e.to_string())?;
                            let cp = u32::from_str_radix(h, 16).map_err(|e| e.to_string())?;
                            self.i += 4;
                            out.push(
                                char::from_u32(cp)
                                    .ok_or_else(|| format!("\\u{:04x} is not a scalar", cp))?,
                            );
                        }
                        e => return Err(format!("bad escape \\{}", e as char)),
                    }
                }
                c if c < 0x20 => {
                    return Err(format!("raw control byte {:#04x} inside a string", c))
                }
                _ => {
                    // Copy this character's UTF-8 byte run verbatim.
                    let start = self.i - 1;
                    let len = if c < 0x80 {
                        1
                    } else if c >> 5 == 0b110 {
                        2
                    } else if c >> 4 == 0b1110 {
                        3
                    } else {
                        4
                    };
                    self.i = start + len;
                    let run = self.b.get(start..self.i).ok_or("truncated UTF-8")?;
                    out.push_str(std::str::from_utf8(run).map_err(|e| e.to_string())?);
                }
            }
        }
    }
    /// A bare non-negative decimal integer. `seq` is a count, so a sign, a
    /// fraction, an exponent or a leading zero is not a spelling of it.
    fn number(&mut self) -> Result<u64, String> {
        let start = self.i;
        while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
            self.i += 1;
        }
        if start == self.i {
            return Err(format!("expected a decimal number at byte {}", start));
        }
        let text = std::str::from_utf8(&self.b[start..self.i]).map_err(|e| e.to_string())?;
        if text.len() > 1 && text.starts_with('0') {
            return Err(format!("seq {:?} has a leading zero", text));
        }
        text.parse::<u64>().map_err(|e| e.to_string())
    }
}

// ---------------------------------------------------------------------------
// §8.2.2 publication identity, §8 chain, §8.4 signed content
// ---------------------------------------------------------------------------

/// The **entry digest** (§8.2.2): SHA-256 over the exact canonical entry line,
/// lowercase hex. This — not the artifact hash, and not `seq` — is the identity
/// of one publication.
///
/// An artifact hash addresses CONTENT: the same artifact may be published more
/// than once (a re-publication of the bound hash is a valid recorded no-op,
/// §8.6.2), so a reader selecting the first or last matching entry is guessing.
/// `seq` is an ordinal that does not survive copying between stores. The digest
/// does both jobs, because `chain` is part of the line and therefore fixes the
/// entry's POSITION as well as its content.
///
/// "The exact canonical entry line" is taken to be the entry's canonical JSON
/// bytes WITHOUT the journal's record-separating LF — the same byte string `chain`
/// and the §8.4 entry signature are computed over. §8.2.2 does not say which,
/// and the two answers are different digests; see DIVERGENCES.md.
pub fn entry_digest(e: &Entry) -> String {
    sha256_hex(encode(e).as_bytes())
}

/// The digest of a line read from a journal, computed over the STORED bytes.
///
/// Strict reading (§8.2.1) has already established that those bytes are the
/// canonical encoding, so this agrees with [`entry_digest`] — but it hashes what
/// the journal actually contains rather than a re-rendering of it, which is the
/// distinction §8.2.1's closing sentence insists on.
pub fn entry_digest_of_line(line: &str) -> Result<String, String> {
    parse(line)?;
    Ok(sha256_hex(line.as_bytes()))
}

/// `chain` for an entry (§8): `SHA-256(anchor + "\n" + entry-bytes)`, lowercase
/// hex, where `entry-bytes` is the canonical encoding with `chain` omitted.
pub fn chain(anchor: &str, e: &Entry) -> String {
    let mut unchained = e.clone();
    unchained.chain = String::new();
    let mut buf = Vec::new();
    buf.extend_from_slice(anchor.as_bytes());
    buf.push(b'\n');
    buf.extend_from_slice(encode(&unchained).as_bytes());
    sha256_hex(&buf)
}

/// The anchor for the first chained entry in a journal that predates the field
/// (§8): SHA-256 of the entire byte prefix before this entry, which
/// retroactively seals the legacy lines.
pub fn legacy_anchor(prefix: &[u8]) -> String {
    sha256_hex(prefix)
}

/// The §8.4 **signed content**: the canonical encoding with the store-assigned
/// `seq`, `time`, `verifier` and `chain`, and `sig` itself, all emptied — so the
/// signature covers exactly the authored fields (including `pubkey`) and is
/// independent of where the entry lands in the log.
pub fn signed_content(e: &Entry) -> String {
    let mut a = e.clone();
    a.seq = 0;
    a.time = String::new();
    a.verifier = String::new();
    a.chain = String::new();
    a.sig = String::new();
    encode(&a)
}

/// Verify the §8.4 entry signature, if the entry claims one.
///
/// `Ok(true)` — a valid signature; `Ok(false)` — the entry is unattributed
/// (neither field present, which imposes no obligation); `Err` — a forged
/// attribution: one field without the other, a malformed key, or a signature
/// that does not verify. §8.4 requires that last case be a REJECTION rather
/// than a downgrade to unattributed.
pub fn verify_entry_signature(e: &Entry) -> Result<bool, String> {
    if e.pubkey.is_empty() && e.sig.is_empty() {
        return Ok(false);
    }
    if e.pubkey.is_empty() || e.sig.is_empty() {
        return Err(
            "an entry with only one of `pubkey`/`sig` is a forged attribution (§8.4)".into(),
        );
    }
    let key = crate::publish::unhex_lower(&e.pubkey)
        .ok_or("pubkey must be lowercase hex (§8.4)")?;
    if key.len() != 32 {
        return Err(format!("pubkey must be 32 bytes, got {}", key.len()));
    }
    let sig = crate::publish::unhex_lower(&e.sig).ok_or("sig must be lowercase hex (§8.4)")?;
    if sig.len() != 64 {
        return Err(format!("sig must be 64 bytes, got {}", sig.len()));
    }
    crate::ed25519::verify(&key, &sig, signed_content(e).as_bytes())
        .map_err(|err| format!("entry signature does not verify: {}", err))?;
    Ok(true)
}

// ---------------------------------------------------------------------------
// §8.6.2 the name revision
// ---------------------------------------------------------------------------

/// What happened to the NAME in an entry (§8.6.3). A different dimension from
/// `status`, which records what the store concluded about the ARTIFACT; §8.6.3
/// says deriving either from the other is unreliable, which is why both exist.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Transition {
    /// The name now points at `hash`. The only value that advances the revision.
    Applied,
    /// A re-publication of the hash already bound: a recorded no-op.
    Unchanged,
    /// No name operation (a `prove` or `cross` entry, a rejection, …).
    None,
}

impl Transition {
    pub fn parse(s: &str) -> Option<Transition> {
        match s {
            "applied" => Some(Transition::Applied),
            "unchanged" => Some(Transition::Unchanged),
            "none" => Some(Transition::None),
            _ => None,
        }
    }
    pub fn as_str(self) -> &'static str {
        match self {
            Transition::Applied => "applied",
            Transition::Unchanged => "unchanged",
            Transition::None => "none",
        }
    }
}

impl Entry {
    /// The transition the entry DECLARES, or `None` for a legacy entry that
    /// carries no `name_transition` member.
    pub fn declared_transition(&self) -> Option<Transition> {
        if self.name_transition.is_empty() {
            None
        } else {
            Transition::parse(&self.name_transition)
        }
    }

    /// The transition to use when counting revisions (§8.6.2).
    ///
    /// When the member is present it is AUTHORITATIVE: §8.6.2 forbids inferring
    /// the transition from `status`, `kind`, `prev` or artifact equality "for any
    /// entry that carries the member", and equally forbids extending the legacy
    /// derivation to such an entry.
    ///
    /// The legacy derivation, for entries written before the member existed:
    ///
    ///  1. a `kind` that is neither `data` nor `func` (nor absent) applied
    ///     nothing — a `prove` or `cross` entry concerns an ARTIFACT and touches
    ///     no name, so counting it would inflate the name's revision;
    ///  2. otherwise `accepted` and `falsified` applied a transition, EXCEPT that
    ///     `prev == hash` was a no-op (`unchanged`);
    ///  3. every other status applied nothing.
    pub fn effective_transition(&self) -> Transition {
        if let Some(t) = self.declared_transition() {
            return t;
        }
        if !self.kind.is_empty() && self.kind != "data" && self.kind != "func" {
            return Transition::None;
        }
        match self.status.as_str() {
            "accepted" | "falsified" => {
                if !self.hash.is_empty() && self.prev == self.hash {
                    Transition::Unchanged
                } else {
                    Transition::Applied
                }
            }
            _ => Transition::None,
        }
    }
}

/// The current revision of `name` (§8.6.2): the number of entries that have
/// APPLIED a transition to it — distinct name STATES, not publications.
///
/// A `BigUint` because §8.6.1 makes `parent_rev` unbounded and forbids a
/// machine-word limit; the counter that produces it must not have one either.
pub fn name_revision(entries: &[Entry], name: &str) -> BigUint {
    let mut rev = BigUint::from(0u32);
    for e in entries {
        if e.name == name && e.effective_transition() == Transition::Applied {
            rev += 1u32;
        }
    }
    rev
}

/// The hash `name` currently resolves to, or `None` when it was never published
/// (§8.6.2: names are only repointed, never deleted, so an unresolvable name is
/// one with no applied transition — `parent=-`, `parent_rev=0`).
pub fn resolve(entries: &[Entry], name: &str) -> Option<String> {
    let mut current = None;
    for e in entries {
        if e.name == name && e.effective_transition() == Transition::Applied {
            current = Some(e.hash.clone());
        }
    }
    current
}

/// Raw SHA-256 of a line, for callers wanting bytes rather than the hex form.
pub fn line_digest_bytes(line: &str) -> [u8; 32] {
    sha256(line.as_bytes())
}

