#[cfg(test)]
mod tests {
    use super::*;

    fn base() -> Entry {
        Entry {
            seq: 12,
            time: "2026-07-29T00:00:00Z".into(),
            author: "claude-main".into(),
            verifier: "oath-kernel/0.7".into(),
            name: "double".into(),
            kind: "func".into(),
            status: "accepted".into(),
            hash: "55".repeat(32),
            prev: "66".repeat(32),
            guarantee: "tested (200 cases per property)".into(),
            termination: "nonrecursive".into(),
            name_transition: "applied".into(),
            ..Entry::default()
        }
    }

    // -- §8.2.1 canonical encoding -------------------------------------------

    #[test]
    fn member_order_is_the_normative_one() {
        let keys: Vec<&str> = MEMBERS.iter().map(|(k, _)| *k).collect();
        assert_eq!(
            keys,
            vec![
                "seq",
                "time",
                "author",
                "verifier",
                "name",
                "kind",
                "status",
                "hash",
                "prev",
                "error",
                "guarantee",
                "termination",
                "context",
                "pubkey",
                "sig",
                "envelope_b64",
                "author_pubkey",
                "author_sig",
                "name_transition",
                "chain",
            ]
        );
    }

    #[test]
    fn encoding_is_compact_and_ordered() {
        let line = encode(&base());
        assert!(!line.contains(' '), "no whitespace: {}", line);
        assert!(!line.ends_with('\n'), "the LF is the record separator, not the entry");
        // Order is observable as the order of the byte offsets.
        let mut last = 0usize;
        for key in [
            "\"seq\"",
            "\"time\"",
            "\"author\"",
            "\"verifier\"",
            "\"name\"",
            "\"kind\"",
            "\"status\"",
            "\"hash\"",
            "\"prev\"",
            "\"guarantee\"",
            "\"termination\"",
            "\"name_transition\"",
        ] {
            let at = line.find(key).unwrap_or_else(|| panic!("missing {}", key));
            assert!(at > last, "{} is out of order in {}", key, line);
            last = at;
        }
    }

    #[test]
    fn empty_members_are_omitted_except_the_always_present_ones() {
        let e = Entry {
            seq: 0,
            name: "n".into(),
            status: "rejected".into(),
            error: "".into(),
            ..Entry::default()
        };
        let line = encode(&e);
        assert_eq!(
            line,
            r#"{"seq":0,"time":"","author":"","verifier":"","name":"n","status":"rejected"}"#
        );
        // and the omitted ones really are omitted
        assert!(!line.contains("error"));
        assert!(!line.contains("chain"));
        assert!(!line.contains("hash"));
    }

    #[test]
    fn a_gate_rejection_carries_no_hash() {
        // §8.2: gate rejection logs contain no object hash.
        let e = Entry {
            seq: 3,
            time: "2026-07-29T00:00:00Z".into(),
            author: "a".into(),
            verifier: "v".into(),
            name: "bad".into(),
            status: "rejected".into(),
            error: "type error".into(),
            name_transition: "none".into(),
            ..Entry::default()
        };
        let line = encode(&e);
        assert!(!line.contains("\"hash\""));
        assert!(line.contains(r#""error":"type error""#));
        assert_eq!(parse(&line).unwrap(), e);
    }

    #[test]
    fn json_escaping_is_minimal() {
        let mut e = base();
        e.error = "a \"quoted\" \\ path\nnext\ttab <&> ©".into();
        let line = encode(&e);
        assert!(line.contains(r#""error":"a \"quoted\" \\ path\nnext\ttab <&> ©""#), "{}", line);
        // `<`, `>`, `&` and non-ASCII stay literal — no HTML escaping, no \u.
        assert!(!line.contains("\\u003c"));
        assert!(!line.contains("\\u00a9"));
        assert_eq!(parse(&line).unwrap(), e);
    }

    #[test]
    fn control_characters_use_the_short_forms_then_u_escapes() {
        let mut e = base();
        e.error = "\u{1}\u{8}\u{c}\u{1f}".into();
        assert!(encode(&e).contains(r#""error":"\b\f""#), "{}", encode(&e));
        assert_eq!(parse(&encode(&e)).unwrap(), e);
    }

    // -- §8.2.1 strict reading ------------------------------------------------

    #[test]
    fn every_canonical_line_round_trips() {
        for e in [base(), Entry::default()] {
            let line = encode(&e);
            assert_eq!(parse(&line).unwrap(), e, "line {}", line);
        }
    }

    #[test]
    fn strict_reading_refuses_reordered_members() {
        let bad = r#"{"time":"","seq":0,"author":"","verifier":"","name":"n","status":"accepted"}"#;
        let err = parse(bad).unwrap_err();
        assert!(err.contains("§8.2.1 fixes the order"), "{}", err);
    }

    #[test]
    fn strict_reading_refuses_unknown_and_duplicated_members() {
        let unknown = r#"{"seq":0,"time":"","author":"","verifier":"","name":"n","status":"accepted","extra":"1"}"#;
        assert!(parse(unknown).unwrap_err().contains("unknown member"));
        let dup = r#"{"seq":0,"time":"","author":"","verifier":"","name":"n","name":"m","status":"accepted"}"#;
        let err = parse(dup).unwrap_err();
        assert!(err.contains("duplicated member") || err.contains("fixes the order"), "{}", err);
    }

    #[test]
    fn strict_reading_refuses_whitespace_and_trailing_content() {
        let ws = r#"{"seq": 0,"time":"","author":"","verifier":"","name":"n","status":"accepted"}"#;
        assert!(parse(ws).is_err(), "a space after the colon is not canonical");
        let ws2 = r#" {"seq":0,"time":"","author":"","verifier":"","name":"n","status":"accepted"}"#;
        assert!(parse(ws2).is_err());
        let trail = r#"{"seq":0,"time":"","author":"","verifier":"","name":"n","status":"accepted"}x"#;
        assert!(parse(trail).unwrap_err().contains("trailing content"));
        let nl = "{\"seq\":0,\"time\":\"\",\"author\":\"\",\"verifier\":\"\",\"name\":\"n\",\"status\":\"accepted\"}\n";
        assert!(parse(nl).is_err(), "the record separator is not part of the entry");
    }

    #[test]
    fn strict_reading_refuses_a_missing_always_present_member() {
        let no_verifier = r#"{"seq":0,"time":"","author":"","name":"n","status":"accepted"}"#;
        assert!(parse(no_verifier).unwrap_err().contains("always present"));
        let no_status = r#"{"seq":0,"time":"","author":"","verifier":"","name":"n"}"#;
        assert!(parse(no_status).unwrap_err().contains("always present"));
    }

    #[test]
    fn strict_reading_refuses_an_equivalent_but_non_canonical_spelling() {
        // A is a legal JSON spelling of "A" and decodes to the same value —
        // and is refused, because chain and signatures are over the BYTES.
        let bad = r#"{"seq":0,"time":"","author":"A","verifier":"","name":"n","status":"accepted"}"#;
        let err = parse(bad).unwrap_err();
        assert!(err.contains("not canonical"), "{}", err);
        // A leading zero on seq likewise.
        let z = r#"{"seq":00,"time":"","author":"","verifier":"","name":"n","status":"accepted"}"#;
        assert!(parse(z).unwrap_err().contains("leading zero"));
    }

    #[test]
    fn strict_reading_refuses_an_unknown_transition_value() {
        let mut e = base();
        e.name_transition = "moved".into();
        let line = encode(&e);
        assert!(parse(&line).unwrap_err().contains("applied|unchanged|none"));
    }

    // -- §8.2.2 publication identity -----------------------------------------

    #[test]
    fn the_entry_digest_is_over_the_canonical_line() {
        let e = base();
        let line = encode(&e);
        assert_eq!(entry_digest(&e), crate::hash::sha256_hex(line.as_bytes()));
        assert_eq!(entry_digest_of_line(&line).unwrap(), entry_digest(&e));
    }

    #[test]
    fn one_artifact_published_twice_has_two_publication_identities() {
        // §8.2.2's motivating case: the artifact hash does not address a
        // publication, so two entries about the same artifact must differ.
        let mut first = base();
        first.chain = "aa".repeat(32);
        let mut second = base();
        second.seq += 1;
        second.prev = first.hash.clone();
        second.name_transition = "unchanged".into();
        second.chain = "bb".repeat(32);
        assert_eq!(first.hash, second.hash, "the same artifact");
        assert_ne!(entry_digest(&first), entry_digest(&second));
    }

    #[test]
    fn the_digest_fixes_position_because_chain_is_in_the_line() {
        let mut a = base();
        a.chain = "11".repeat(32);
        let mut b = a.clone();
        b.chain = "22".repeat(32);
        assert_ne!(entry_digest(&a), entry_digest(&b));
    }

    // -- §8 chain, §8.4 signed content ---------------------------------------

    #[test]
    fn chain_is_over_the_unchained_canonical_bytes() {
        let mut e = base();
        e.chain = "ff".repeat(32); // must be ignored by the computation
        let anchor = "00".repeat(32);
        let mut unchained = e.clone();
        unchained.chain = String::new();
        let want = crate::hash::sha256_hex(
            &[anchor.as_bytes(), b"\n", encode(&unchained).as_bytes()].concat(),
        );
        assert_eq!(chain(&anchor, &e), want);
    }

    #[test]
    fn signed_content_drops_the_store_assigned_fields() {
        let mut e = base();
        e.pubkey = "ab".repeat(32);
        e.sig = "cd".repeat(64);
        e.chain = "ef".repeat(32);
        let sc = signed_content(&e);
        assert!(sc.contains(r#""seq":0"#));
        assert!(sc.contains(r#""time":"""#));
        assert!(sc.contains(r#""verifier":"""#));
        assert!(!sc.contains("\"sig\""));
        assert!(!sc.contains("\"chain\""));
        // …but keeps `pubkey`, so the signature covers the signer's own claim.
        assert!(sc.contains(&format!(r#""pubkey":"{}""#, "ab".repeat(32))));
        // and is independent of where the entry lands
        let mut moved = e.clone();
        moved.seq = 999;
        moved.time = "2030-01-01T00:00:00Z".into();
        moved.verifier = "oath-kernel/9".into();
        moved.chain = "00".repeat(32);
        assert_eq!(signed_content(&moved), sc);
    }

    #[test]
    fn entry_signatures_verify_and_forgeries_do_not() {
        let seed: [u8; 32] = (1u8..=32).collect::<Vec<u8>>().try_into().unwrap();
        let pk = crate::ed25519::public_key(&seed);
        let mut e = base();
        e.pubkey = crate::publish::hex_lower(&pk);
        // Unattributed until both fields are set.
        let mut none = base();
        assert_eq!(verify_entry_signature(&none), Ok(false));
        none.pubkey = e.pubkey.clone();
        assert!(verify_entry_signature(&none).is_err(), "pubkey with no sig is forged");

        let sig = crate::ed25519::sign(&seed, signed_content(&e).as_bytes());
        e.sig = crate::publish::hex_lower(&sig);
        assert_eq!(verify_entry_signature(&e), Ok(true));

        // Moving the entry in the log does not break it (§8.4).
        let mut moved = e.clone();
        moved.seq = 77;
        moved.time = "2030-01-01T00:00:00Z".into();
        moved.chain = "aa".repeat(32);
        assert_eq!(verify_entry_signature(&moved), Ok(true));

        // Altering an authored field does.
        let mut tampered = e.clone();
        tampered.hash = "99".repeat(32);
        assert!(verify_entry_signature(&tampered).is_err());
    }

    // -- §8.6.2 the name revision --------------------------------------------

    fn ent(name: &str, kind: &str, status: &str, hash: &str, prev: &str, t: &str) -> Entry {
        Entry {
            seq: 1,
            name: name.into(),
            kind: kind.into(),
            status: status.into(),
            hash: hash.into(),
            prev: prev.into(),
            name_transition: t.into(),
            ..Entry::default()
        }
    }

    #[test]
    fn the_revision_counts_states_not_publications() {
        // The §8.6.2 table, in order: (none)→A, A→B, A→A, no name operation.
        let a = "aa".repeat(32);
        let b = "bb".repeat(32);
        let log = vec![
            ent("n", "func", "accepted", &a, "", "applied"),
            ent("n", "func", "accepted", &b, &a, "applied"),
            ent("n", "func", "accepted", &b, &b, "unchanged"),
            ent("n", "prove", "accepted", &b, "", "none"),
        ];
        assert_eq!(name_revision(&log, "n"), BigUint::from(2u32));
        assert_eq!(resolve(&log, "n"), Some(b.clone()));

        // A re-publication of the bound hash is a recorded no-op: it must NOT
        // invalidate an envelope prepared against the unchanged state.
        assert_eq!(
            name_revision(&log[..3], "n"),
            name_revision(&log[..2], "n"),
            "an unchanged binding is not a new version of it"
        );
    }

    #[test]
    fn aba_protection_survives_the_hash_becoming_valid_again() {
        let a = "aa".repeat(32);
        let b = "bb".repeat(32);
        let log = vec![
            ent("n", "func", "accepted", &a, "", "applied"),
            ent("n", "func", "accepted", &b, &a, "applied"),
            ent("n", "func", "accepted", &a, &b, "applied"),
        ];
        // The parent hash is `a` again at revision 1 and at revision 3, but the
        // revision is not, so the historical envelope no longer applies.
        assert_eq!(name_revision(&log[..1], "n"), BigUint::from(1u32));
        assert_eq!(name_revision(&log, "n"), BigUint::from(3u32));
    }

    #[test]
    fn a_falsified_definition_still_binds_its_name() {
        // §8.6.2/§8.6.3: `status` is about the ARTIFACT, `name_transition` about
        // the NAME, and a falsified def binds.
        let a = "aa".repeat(32);
        let log = vec![ent("n", "func", "falsified", &a, "", "applied")];
        assert_eq!(name_revision(&log, "n"), BigUint::from(1u32));
        assert_eq!(resolve(&log, "n"), Some(a));
    }

    #[test]
    fn rejected_blocked_and_pending_move_nothing() {
        let a = "aa".repeat(32);
        for status in ["rejected", "blocked", "pending"] {
            let log = vec![ent("n", "func", status, &a, "", "none")];
            assert_eq!(
                name_revision(&log, "n"),
                BigUint::from(0u32),
                "{} must not advance the revision",
                status
            );
            assert_eq!(resolve(&log, "n"), None);
        }
    }

    #[test]
    fn the_declared_member_overrides_every_inference() {
        // §8.6.2: for an entry that CARRIES the member, the transition MUST NOT
        // be inferred from status, kind, prev or artifact equality.
        let a = "aa".repeat(32);
        // An accepted func whose prev != hash — the legacy rule would say
        // `applied` — but the member says otherwise, and the member wins.
        let e = ent("n", "func", "accepted", &a, &"bb".repeat(32), "none");
        assert_eq!(e.effective_transition(), Transition::None);
        // A prove-kind entry that DECLARES applied is counted, kind
        // notwithstanding: the kind restriction is part of the LEGACY
        // derivation only.
        let p = ent("n", "prove", "accepted", &a, "", "applied");
        assert_eq!(p.effective_transition(), Transition::Applied);
    }

    #[test]
    fn legacy_entries_derive_the_transition_with_the_kind_restriction() {
        let a = "aa".repeat(32);
        let b = "bb".repeat(32);
        // kind neither data nor func nor absent: applied nothing.
        for kind in ["prove", "cross"] {
            let e = ent("n", kind, "accepted", &a, "", "");
            assert_eq!(
                e.effective_transition(),
                Transition::None,
                "a legacy {} entry concerns an artifact, not a name",
                kind
            );
        }
        // data, func, and an ABSENT kind all derive from the status.
        for kind in ["data", "func", ""] {
            let e = ent("n", kind, "accepted", &a, "", "");
            assert_eq!(e.effective_transition(), Transition::Applied, "kind {:?}", kind);
            let f = ent("n", kind, "falsified", &a, &b, "");
            assert_eq!(f.effective_transition(), Transition::Applied);
            for status in ["rejected", "blocked", "pending"] {
                let x = ent("n", kind, status, &a, "", "");
                assert_eq!(x.effective_transition(), Transition::None, "{}", status);
            }
        }
        // prev == hash was a no-op even when accepted.
        let same = ent("n", "func", "accepted", &a, &a, "");
        assert_eq!(same.effective_transition(), Transition::Unchanged);
        // A legacy log mixing all of these counts only the applied ones.
        let log = vec![
            ent("n", "func", "accepted", &a, "", ""),
            ent("n", "prove", "accepted", &a, "", ""),
            ent("n", "func", "accepted", &a, &a, ""),
            ent("n", "func", "accepted", &b, &a, ""),
            ent("n", "func", "rejected", "", "", ""),
            ent("other", "func", "accepted", &b, "", ""),
        ];
        assert_eq!(name_revision(&log, "n"), BigUint::from(2u32));
        assert_eq!(name_revision(&log, "other"), BigUint::from(1u32));
    }

    #[test]
    fn the_revision_is_per_name() {
        let a = "aa".repeat(32);
        let log = vec![
            ent("x", "func", "accepted", &a, "", "applied"),
            ent("y", "func", "accepted", &a, "", "applied"),
            ent("x", "func", "accepted", &a, &a, "unchanged"),
        ];
        assert_eq!(name_revision(&log, "x"), BigUint::from(1u32));
        assert_eq!(name_revision(&log, "y"), BigUint::from(1u32));
        assert_eq!(name_revision(&log, "never-published"), BigUint::from(0u32));
        assert_eq!(resolve(&log, "never-published"), None);
    }
}

