//! Signed publication — the author's statement (SPEC §8.6, #87).
//!
//! §8.4 signs a journal ENTRY, which seals custody: the record has not been
//! altered since the store wrote it. It does not establish authorship to a third
//! party, because the store composed the entry and could have composed one naming
//! anyone. A **publication envelope** is the author's own statement, signed
//! before submission and persisted verbatim, so authorship is checkable without
//! trusting the store.
//!
//! The envelope covers only what the author controls — the name, the artifact and
//! the transition. It deliberately does NOT cover store-derived verdicts
//! (`status`, `guarantee`, `termination`, the policy outcome): those are
//! re-derivable from content bytes, an author cannot predict them, and requiring
//! a signature over them would make a policy decision indistinguishable from a
//! forged statement.
//!
//! Everything in this module is byte-exact on purpose. The envelope octets are
//! what a signature is computed over, so one differing byte is not a visible
//! error — it makes every signature this kernel produces unverifiable by another
//! kernel and vice versa. The signature stays *correct* and stops *verifying*.
//! That is why encoding is paired with a strict parser (§8.6.1) that re-encodes
//! and compares: canonical writing with lenient reading would protect identity at
//! creation and discard it at verification.
//!
//! Metadata only (§9): none of this reaches definition identity.

use crate::ed25519;
use crate::journal::Entry;
use num_bigint::BigUint;

/// The format tag line (§8.6.1). It is INSIDE the signed octets, so a signature
/// made under one format version can never be read under another.
pub const ENVELOPE_FORMAT: &str = "oath-publish/1";

/// The six `key=value` keys, in the normative order (§8.6.1).
pub const ENVELOPE_KEYS: [&str; 6] = ["op", "name", "artifact", "parent", "parent_rev", "author"];

/// The `parent` sentinel meaning the name had no previous value (§8.6.1).
pub const NO_PARENT: &str = "-";

/// A publication envelope (§8.6.1).
///
/// Field declaration order is the normative encoding order and is not free to
/// change.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Envelope {
    /// `put` — the only operation this version defines.
    pub op: String,
    /// The name being published. Non-empty; MAY contain `=` (§8.6.1).
    pub name: String,
    /// The artifact's content hash: 64 lowercase hex.
    pub artifact: String,
    /// The hash the name currently points at, or `None` for the `-` sentinel.
    pub parent: Option<String>,
    /// The name's current revision (§8.6.2). **Unbounded** — §8.6.1 forbids a
    /// machine-word limit, because imposing one would declare a valid historical
    /// statement malformed once a name had been repointed often enough. Hence
    /// `BigUint` and not `u64`.
    pub parent_rev: BigUint,
    /// The signing key: 64 lowercase hex of a 32-byte Ed25519 public key.
    pub author: String,
}

impl Envelope {
    /// A first publication: the `-` sentinel and revision 0 (§8.6.1 requires
    /// both or neither).
    pub fn first(name: &str, artifact: &str, author: &str) -> Envelope {
        Envelope {
            op: "put".into(),
            name: name.into(),
            artifact: artifact.into(),
            parent: None,
            parent_rev: BigUint::from(0u32),
            author: author.into(),
        }
    }

    /// A repoint over a known parent at a known revision.
    pub fn repoint(
        name: &str,
        artifact: &str,
        parent: &str,
        parent_rev: BigUint,
        author: &str,
    ) -> Envelope {
        Envelope {
            op: "put".into(),
            name: name.into(),
            artifact: artifact.into(),
            parent: Some(parent.into()),
            parent_rev,
            author: author.into(),
        }
    }

    /// The `parent` field as it appears in the encoding.
    pub fn parent_field(&self) -> &str {
        match &self.parent {
            Some(h) => h,
            None => NO_PARENT,
        }
    }

    /// Every §8.6.1 rejection rule, checked on BOTH the encoding and the
    /// verification side, as §8.6.1 requires ("MUST reject an envelope, on both
    /// encoding and verification, unless all of…").
    pub fn validate(&self) -> Result<(), String> {
        // The character rule comes first: it is the one that keeps the encoding
        // uniquely decodable, and §8.6.1 notes it is reachable only from the
        // ENCODING side (an injected LF in stored octets presents as a
        // line-count error, never as "a value contained an LF").
        for (key, value) in [
            ("op", self.op.as_str()),
            ("name", self.name.as_str()),
            ("artifact", self.artifact.as_str()),
            ("parent", self.parent_field()),
            ("author", self.author.as_str()),
        ] {
            if let Some(c) = value.chars().find(|c| (*c as u32) < 0x20 || *c as u32 == 0x7f) {
                return Err(format!(
                    "{}: value contains the forbidden character U+{:04X}",
                    key, c as u32
                ));
            }
        }
        if self.op != "put" {
            return Err(format!(
                "op must be `put`, the only operation this version defines, got {:?}",
                self.op
            ));
        }
        if self.name.is_empty() {
            return Err("name must be non-empty".into());
        }
        if !is_lower_hash(&self.artifact) {
            return Err(format!(
                "artifact must be 64 lowercase hex characters, got {:?}",
                self.artifact
            ));
        }
        if let Some(p) = &self.parent {
            if !is_lower_hash(p) {
                return Err(format!(
                    "parent must be 64 lowercase hex characters or `-`, got {:?}",
                    p
                ));
            }
        }
        if !is_lower_hash(&self.author) {
            return Err(format!(
                "author must be 64 lowercase hex characters, got {:?}",
                self.author
            ));
        }
        // `parent` is `-` IF AND ONLY IF `parent_rev` is 0. Allowing them to
        // disagree would let one envelope describe two different states.
        let zero = self.parent_rev == BigUint::from(0u32);
        match (&self.parent, zero) {
            (None, false) => Err(format!(
                "parent is `-` but parent_rev is {}; a first publication has both or neither",
                self.parent_rev
            )),
            (Some(_), true) => {
                Err("parent is a hash but parent_rev is 0; a first publication has both or neither"
                    .into())
            }
            _ => Ok(()),
        }
    }
}

/// The canonical envelope octets (§8.6.1): the format tag line, then exactly six
/// `key=value` lines in the normative order, each terminated by one LF. No other
/// whitespace, no trailing content, no optional field.
///
/// The octets are UTF-8 (§8.6.1). A reader never needs to decode them — the
/// signature is over bytes — but a name may contain non-ASCII, and two encodings
/// of one name would be two different statements, so the encoding side commits to
/// one.
pub fn encode(env: &Envelope) -> Result<Vec<u8>, String> {
    env.validate()?;
    let rev = env.parent_rev.to_str_radix(10);
    let mut out = String::new();
    out.push_str(ENVELOPE_FORMAT);
    out.push('\n');
    for (key, value) in [
        ("op", env.op.as_str()),
        ("name", env.name.as_str()),
        ("artifact", env.artifact.as_str()),
        ("parent", env.parent_field()),
        ("parent_rev", rev.as_str()),
        ("author", env.author.as_str()),
    ] {
        out.push_str(key);
        out.push('=');
        out.push_str(value);
        out.push('\n');
    }
    Ok(out.into_bytes())
}

/// Strict parsing (§8.6.1). Unknown keys, missing keys, duplicated keys,
/// reordered keys, a missing trailing LF and trailing bytes are all errors — and
/// the parsed value MUST re-encode to the input bytes exactly.
///
/// The line grammar is fixed and closed, so key identity carries all four of
/// those errors at once: position `i` must hold key `ENVELOPE_KEYS[i]`, and
/// anything else is one of unknown / missing / duplicated / reordered depending
/// on how you read it.
pub fn parse(octets: &[u8]) -> Result<Envelope, String> {
    let text = std::str::from_utf8(octets)
        .map_err(|e| format!("envelope octets are not UTF-8 (§8.6.1): {}", e))?;
    if !text.ends_with('\n') {
        return Err("envelope must end with an LF; framing is part of the encoding".into());
    }
    // `split('\n')` on LF-terminated text yields a final empty element; every
    // other element is one line, with its own LF already accounted for.
    let mut lines: Vec<&str> = text.split('\n').collect();
    let last = lines.pop();
    debug_assert_eq!(last, Some(""));
    if lines.len() != 1 + ENVELOPE_KEYS.len() {
        return Err(format!(
            "envelope must be {} lines (the format tag and {} fields), got {}",
            1 + ENVELOPE_KEYS.len(),
            ENVELOPE_KEYS.len(),
            lines.len()
        ));
    }
    if lines[0] != ENVELOPE_FORMAT {
        return Err(format!(
            "format tag must be exactly {:?}, got {:?}; a different tag is not a newer envelope \
             to be interpreted but one this version cannot verify",
            ENVELOPE_FORMAT, lines[0]
        ));
    }
    let mut values: Vec<&str> = Vec::with_capacity(ENVELOPE_KEYS.len());
    for (i, key) in ENVELOPE_KEYS.iter().enumerate() {
        let line = lines[i + 1];
        // Split at the FIRST `=` (§8.6.1): `name=a=b` names `a=b`.
        let (k, v) = line
            .split_once('=')
            .ok_or_else(|| format!("line {:?} is not `key=value`", line))?;
        if k != *key {
            return Err(format!(
                "field {} must be {:?}, got {:?}; §8.6.1 fixes the key set and their order",
                i + 1,
                key,
                k
            ));
        }
        values.push(v);
    }
    let parent = if values[3] == NO_PARENT {
        None
    } else {
        Some(values[3].to_string())
    };
    let env = Envelope {
        op: values[0].to_string(),
        name: values[1].to_string(),
        artifact: values[2].to_string(),
        parent,
        parent_rev: parse_canonical_decimal(values[4])?,
        author: values[5].to_string(),
    };
    env.validate()?;
    // §8.6.1: re-encoding the parsed value MUST reproduce the input exactly.
    let re = encode(&env)?;
    if re != octets {
        return Err(format!(
            "envelope is not canonical: re-encoding gives {:?}, input was {:?}",
            String::from_utf8_lossy(&re),
            text
        ));
    }
    Ok(env)
}

/// `parent_rev` (§8.6.1): a non-negative integer in canonical decimal — no
/// leading zeros, no sign, no spaces. `03` and `+3` are rejected because they
/// would be distinct bytes for one revision. UNBOUNDED: there is no width limit
/// here, deliberately.
fn parse_canonical_decimal(s: &str) -> Result<BigUint, String> {
    if s.is_empty() {
        return Err("parent_rev must be a decimal integer, got an empty value".into());
    }
    if !s.bytes().all(|b| b.is_ascii_digit()) {
        return Err(format!(
            "parent_rev must be decimal digits only — no sign, no spaces — got {:?}",
            s
        ));
    }
    if s.len() > 1 && s.starts_with('0') {
        return Err(format!(
            "parent_rev {:?} has a leading zero; {:?} and {:?} would be different bytes for one \
             revision",
            s,
            s,
            s.trim_start_matches('0')
        ));
    }
    BigUint::parse_bytes(s.as_bytes(), 10).ok_or_else(|| format!("bad decimal {:?}", s))
}

fn is_lower_hash(s: &str) -> bool {
    s.len() == 64 && s.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

/// Sign an envelope: encode it, then sign the OCTETS (§8.6.3 — never a
/// re-encoding, never the base64 text). Returns the octets that must be
/// persisted verbatim alongside the signature.
pub fn sign_envelope(seed: &[u8; 32], env: &Envelope) -> Result<(Vec<u8>, [u8; 64]), String> {
    let octets = encode(env)?;
    let author = hex_lower(&ed25519::public_key(seed));
    if env.author != author {
        return Err(format!(
            "envelope names author {:?} but the seed's key is {:?}",
            env.author, author
        ));
    }
    let sig = ed25519::sign(seed, &octets);
    Ok((octets, sig))
}

// ---------------------------------------------------------------------------
// §8.6.3 the base64 storage representation
// ---------------------------------------------------------------------------

const B64: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/// Base64 in the dialect §8.6.3 pins: RFC 4648 §4 **standard** alphabet (`+` and
/// `/`), padding **required**, no line breaks, no whitespace, no URL-safe
/// substitutions.
pub fn b64_encode(bytes: &[u8]) -> String {
    let mut out = String::with_capacity((bytes.len() + 2) / 3 * 4);
    for group in bytes.chunks(3) {
        let b0 = group[0] as u32;
        let b1 = *group.get(1).unwrap_or(&0) as u32;
        let b2 = *group.get(2).unwrap_or(&0) as u32;
        let n = (b0 << 16) | (b1 << 8) | b2;
        out.push(B64[(n >> 18) as usize & 63] as char);
        out.push(B64[(n >> 12) as usize & 63] as char);
        if group.len() > 1 {
            out.push(B64[(n >> 6) as usize & 63] as char);
        } else {
            out.push('=');
        }
        if group.len() > 2 {
            out.push(B64[n as usize & 63] as char);
        } else {
            out.push('=');
        }
    }
    out
}

/// Decode base64 in the pinned dialect, refusing everything outside it: any
/// character not in the standard alphabet (so no `-`/`_`, no whitespace
/// anywhere, no line breaks), a length that is not a multiple of four (so
/// unpadded input), and `=` anywhere but the final group.
pub fn b64_decode(s: &str) -> Result<Vec<u8>, String> {
    let b = s.as_bytes();
    if b.len() % 4 != 0 {
        return Err(format!(
            "base64 length {} is not a multiple of 4; the pinned dialect requires padding",
            b.len()
        ));
    }
    let mut out = Vec::with_capacity(b.len() / 4 * 3);
    let groups = b.len() / 4;
    for g in 0..groups {
        let quad = &b[g * 4..g * 4 + 4];
        let mut vals = [0u32; 4];
        let mut pads = 0;
        for (i, c) in quad.iter().enumerate() {
            if *c == b'=' {
                // Padding is only ever the last one or two characters of the
                // LAST group.
                if g + 1 != groups || i < 2 {
                    return Err(format!("misplaced padding at byte {}", g * 4 + i));
                }
                pads += 1;
                vals[i] = 0;
                continue;
            }
            if pads > 0 {
                return Err(format!("base64 character after padding at byte {}", g * 4 + i));
            }
            let v = B64
                .iter()
                .position(|a| a == c)
                .ok_or_else(|| {
                    format!(
                        "byte {:#04x} at offset {} is not in the RFC 4648 §4 standard alphabet",
                        c,
                        g * 4 + i
                    )
                })?;
            vals[i] = v as u32;
        }
        let n = (vals[0] << 18) | (vals[1] << 12) | (vals[2] << 6) | vals[3];
        out.push((n >> 16) as u8);
        if pads < 2 {
            out.push((n >> 8) as u8);
        }
        if pads < 1 {
            out.push(n as u8);
        }
    }
    Ok(out)
}

/// Recover the envelope octets from an `envelope_b64` member (§8.6.3).
///
/// Two obligations, not one: the member must decode in the pinned dialect, AND
/// re-encoding the decoded octets must reproduce the member exactly. The second
/// is what refuses alternate spellings that decode to the same octets from
/// different stored bytes — `AR==` and `AQ==` both decode to `0x01`, and the
/// member is itself compared and re-encoded as part of the canonical entry
/// (§8.2.1), so only one of them can be the stored form.
pub fn envelope_octets(member: &str) -> Result<Vec<u8>, String> {
    let octets = b64_decode(member)?;
    let re = b64_encode(&octets);
    if re != member {
        return Err(format!(
            "envelope_b64 is not canonical base64: re-encoding the decoded octets gives {:?}",
            re
        ));
    }
    Ok(octets)
}

// ---------------------------------------------------------------------------
// hex — the rendering §8.4 and §8.6.3 use for keys and signatures
// ---------------------------------------------------------------------------

pub fn hex_lower(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
        s.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
    }
    s
}

/// Decode LOWERCASE hex, refusing uppercase. Every hex field in §8.4/§8.6 is
/// specified as lowercase, and these fields sit inside byte-compared canonical
/// encodings, so accepting uppercase would admit a second spelling of one value.
pub fn unhex_lower(s: &str) -> Option<Vec<u8>> {
    if s.len() % 2 != 0 {
        return None;
    }
    let mut out = Vec::with_capacity(s.len() / 2);
    let b = s.as_bytes();
    let val = |c: u8| -> Option<u8> {
        match c {
            b'0'..=b'9' => Some(c - b'0'),
            b'a'..=b'f' => Some(c - b'a' + 10),
            _ => None,
        }
    };
    for pair in b.chunks(2) {
        out.push((val(pair[0])? << 4) | val(pair[1])?);
    }
    Some(out)
}

// ---------------------------------------------------------------------------
// §8.6.4 verification obligations
// ---------------------------------------------------------------------------

/// Verify the publication fields of a journal entry (§8.6.4).
///
/// `Ok(None)` — the entry carries none of the three fields, which imposes no
/// obligation and is conformant. `Ok(Some(env))` — all five clauses hold.
/// `Err(..)` — the journal MUST be rejected.
///
/// Clause (5) deserves its emphasis: an envelope whose `name`, `artifact` or
/// `parent` disagrees with the entry means the store recorded a transition its
/// author did not sign. §8.6.4 makes that a hard failure, never a warning.
pub fn verify_entry_publication(e: &Entry) -> Result<Option<Envelope>, String> {
    let present = [
        !e.envelope_b64.is_empty(),
        !e.author_pubkey.is_empty(),
        !e.author_sig.is_empty(),
    ];
    if present.iter().all(|p| !p) {
        return Ok(None);
    }
    // (1) all three present. Any one alone attests to nothing.
    if !present.iter().all(|p| *p) {
        return Err(format!(
            "a publication needs all of envelope_b64/author_pubkey/author_sig; \
             present: envelope_b64={}, author_pubkey={}, author_sig={} (§8.6.4)",
            present[0], present[1], present[2]
        ));
    }
    // (2) `envelope` parses under §8.6.1 and re-encodes to itself. The member is
    // base64 (§8.6.3), so the pinned dialect is part of this step.
    let octets = envelope_octets(&e.envelope_b64)?;
    let env = parse(&octets)?;
    // (3) the envelope's `author` equals `author_pubkey`.
    if env.author != e.author_pubkey {
        return Err(format!(
            "envelope author {:?} is not the entry's author_pubkey {:?} (§8.6.4.3)",
            env.author, e.author_pubkey
        ));
    }
    // (4) a valid signature over the octets DECODED FROM the member — not over a
    // re-encoding of the parsed envelope, and not over the base64 text.
    let key = unhex_lower(&e.author_pubkey)
        .ok_or("author_pubkey must be lowercase hex (§8.6.3)")?;
    if key.len() != 32 {
        return Err(format!("author_pubkey must be 32 bytes, got {}", key.len()));
    }
    let sig = unhex_lower(&e.author_sig).ok_or("author_sig must be lowercase hex (§8.6.3)")?;
    if sig.len() != 64 {
        return Err(format!("author_sig must be 64 bytes, got {}", sig.len()));
    }
    ed25519::verify(&key, &sig, &octets)
        .map_err(|err| format!("author_sig does not verify over the envelope octets: {}", err))?;
    // (5) name / artifact / parent agree with the entry, with an empty `prev`
    // corresponding to `-`.
    if env.name != e.name {
        return Err(format!(
            "envelope names {:?} but the entry names {:?} (§8.6.4.5)",
            env.name, e.name
        ));
    }
    if env.artifact != e.hash {
        return Err(format!(
            "envelope artifact {:?} is not the entry's hash {:?} (§8.6.4.5)",
            env.artifact, e.hash
        ));
    }
    let entry_parent = if e.prev.is_empty() { NO_PARENT } else { e.prev.as_str() };
    if env.parent_field() != entry_parent {
        return Err(format!(
            "envelope parent {:?} is not the entry's prev {:?}: the store recorded a transition \
             its author did not sign (§8.6.4.5)",
            env.parent_field(),
            entry_parent
        ));
    }
    Ok(Some(env))
}

/// The name state a store compares a publication against (§8.6.4).
pub struct NameState<'a> {
    /// The hash the name currently points at, or `None` when never published.
    pub parent: Option<&'a str>,
    /// The name's current revision (§8.6.2).
    pub rev: BigUint,
}

/// The checks a store MUST make **before** the name moves (§8.6.4).
///
/// `principal` is the AUTHENTICATED principal's public key — not the key the
/// envelope names. Verifying against the envelope's own `author` would always
/// succeed, so a caller could submit any valid statement made by anyone; this is
/// the difference between "this statement is genuine" and "this statement is
/// yours".
///
/// `recomputed_artifact` is the hash the store computed FROM THE SUBMITTED
/// CONTENT. Because identity is a pure function of content (§1), requiring it to
/// equal the signed `artifact` makes agreement between the client's and the
/// store's elaboration an enforced precondition rather than an assumption.
///
/// Note what this is not: §8.6.5 is explicit that the envelope expresses a
/// compare-and-swap and does not by itself make application atomic. This
/// function is the COMPARE. A store that cannot perform the compare and the
/// update in one atomic operation MUST NOT claim atomic signed transitions.
pub fn check_before_move(
    octets: &[u8],
    author_sig: &[u8],
    principal: &[u8],
    recomputed_artifact: &str,
    state: &NameState,
) -> Result<Envelope, String> {
    let env = parse(octets)?;
    if hex_lower(principal) != env.author {
        return Err(format!(
            "the envelope was signed as {:?} but the authenticated principal is {:?}; a valid \
             statement by someone else is not this caller's statement (§8.6.4)",
            env.author,
            hex_lower(principal)
        ));
    }
    ed25519::verify(principal, author_sig, octets)
        .map_err(|e| format!("author_sig does not verify under the principal's key: {}", e))?;
    if env.artifact != recomputed_artifact {
        return Err(format!(
            "signed artifact {:?} is not the hash the store computed from the submitted content \
             ({:?}) (§8.6.4)",
            env.artifact, recomputed_artifact
        ));
    }
    let current = state.parent.unwrap_or(NO_PARENT);
    if env.parent_field() != current {
        return Err(format!(
            "signed parent {:?} is not the name's current value {:?} (§8.6.4)",
            env.parent_field(),
            current
        ));
    }
    if env.parent_rev != state.rev {
        return Err(format!(
            "signed parent_rev {} is not the name's current revision {} (§8.6.4)",
            env.parent_rev, state.rev
        ));
    }
    Ok(env)
}

