#[cfg(test)]
mod tests {
    use super::*;
    use crate::journal;

    fn seed32() -> [u8; 32] {
        (1u8..=32).collect::<Vec<u8>>().try_into().unwrap()
    }

    fn enc(env: &Envelope) -> String {
        String::from_utf8(encode(env).expect("valid envelope")).unwrap()
    }

    // -- §8.6.1 canonical encoding -------------------------------------------

    #[test]
    fn first_publication_encodes_with_the_sentinel_and_revision_zero() {
        let env = Envelope::first("double", &"11".repeat(32), &"aa".repeat(32));
        assert_eq!(
            enc(&env),
            concat!(
                "oath-publish/1\n",
                "op=put\n",
                "name=double\n",
                "artifact=1111111111111111111111111111111111111111111111111111111111111111\n",
                "parent=-\n",
                "parent_rev=0\n",
                "author=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n",
            )
        );
        assert_eq!(parse(&encode(&env).unwrap()).unwrap(), env);
    }

    #[test]
    fn the_format_tag_is_the_first_line_and_inside_the_signed_bytes() {
        let env = Envelope::first("n", &"ab".repeat(32), &"cd".repeat(32));
        let octets = encode(&env).unwrap();
        assert!(octets.starts_with(b"oath-publish/1\n"));
        // Swapping the tag makes different signed bytes, which is the point.
        let mut two = String::from_utf8(octets.clone()).unwrap();
        two = two.replacen("oath-publish/1", "oath-publish/2", 1);
        assert_ne!(two.as_bytes(), octets.as_slice());
        let err = parse(two.as_bytes()).unwrap_err();
        assert!(err.contains("format tag"), "{}", err);
    }

    #[test]
    fn a_name_may_contain_an_equals_sign() {
        // §8.6.1: parsing splits each line at its FIRST `=`, so `name=a=b` names
        // `a=b` and is not ambiguous.
        let env = Envelope::first("a=b", &"11".repeat(32), &"aa".repeat(32));
        let octets = encode(&env).unwrap();
        assert!(enc(&env).contains("\nname=a=b\n"));
        assert_eq!(parse(&octets).unwrap().name, "a=b");
        // And a name that looks like a whole field line is still just a name.
        let sneaky = Envelope::first("x=1\tparent=-", &"11".repeat(32), &"aa".repeat(32));
        assert_eq!(parse(&encode(&sneaky).unwrap()).unwrap(), sneaky);
    }

    #[test]
    fn the_octets_are_utf8_and_a_name_may_be_non_ascii() {
        let env = Envelope::first("michael/café-∑", &"11".repeat(32), &"aa".repeat(32));
        let octets = encode(&env).unwrap();
        assert_eq!(std::str::from_utf8(&octets).unwrap().lines().count(), 7);
        assert_eq!(parse(&octets).unwrap(), env);
        // Invalid UTF-8 in the octets is refused rather than lossily decoded.
        let mut bad = octets.clone();
        let at = bad.iter().position(|b| *b == 0xc3).unwrap();
        bad[at] = 0xff;
        assert!(parse(&bad).unwrap_err().contains("UTF-8"));
    }

    #[test]
    fn parent_rev_is_unbounded() {
        // §8.6.1 forbids a machine-word limit: a name repointed often enough must
        // not make a valid historical statement malformed.
        let huge = BigUint::parse_bytes(b"340282366920938463463374607431768211457", 10).unwrap();
        assert!(huge > BigUint::from(u64::MAX));
        let env = Envelope::repoint(
            "n",
            &"11".repeat(32),
            &"22".repeat(32),
            huge.clone(),
            &"aa".repeat(32),
        );
        let octets = encode(&env).unwrap();
        assert!(enc(&env).contains("parent_rev=340282366920938463463374607431768211457\n"));
        assert_eq!(parse(&octets).unwrap().parent_rev, huge);
    }

    #[test]
    fn multi_digit_revisions_are_bare_decimal() {
        let env = Envelope::repoint(
            "michael/service1/verify-webhook",
            &"33".repeat(32),
            &"44".repeat(32),
            BigUint::from(1042u32),
            &"cc".repeat(32),
        );
        assert!(enc(&env).contains("parent_rev=1042\n"));
    }

    // -- §8.6.1 rejections ----------------------------------------------------

    #[test]
    fn uppercase_hex_is_rejected() {
        let mut env = Envelope::first("n", &"AB".repeat(32), &"aa".repeat(32));
        assert!(encode(&env).unwrap_err().contains("artifact"));
        env.artifact = "ab".repeat(32);
        env.author = "AA".repeat(32);
        assert!(encode(&env).unwrap_err().contains("author"));
        // …and on the parse side too.
        let bad = "oath-publish/1\nop=put\nname=n\nartifact=ABABABABABABABABABABABABABABABABABABABABABABABABABABABABABABABAB\nparent=-\nparent_rev=0\nauthor=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n";
        assert!(parse(bad.as_bytes()).unwrap_err().contains("lowercase"));
    }

    #[test]
    fn non_canonical_revisions_are_rejected() {
        for bad in ["01", "+3", "-1", " 1", "1 ", "", "0x1", "١"] {
            let text = format!(
                "oath-publish/1\nop=put\nname=n\nartifact={}\nparent={}\nparent_rev={}\nauthor={}\n",
                "ab".repeat(32),
                "cd".repeat(32),
                bad,
                "aa".repeat(32)
            );
            assert!(
                parse(text.as_bytes()).is_err(),
                "parent_rev {:?} must be rejected",
                bad
            );
        }
    }

    #[test]
    fn the_parent_sentinel_and_revision_zero_must_agree() {
        let mut env = Envelope::first("n", &"ab".repeat(32), &"aa".repeat(32));
        env.parent_rev = BigUint::from(2u32);
        assert!(encode(&env).unwrap_err().contains("both or neither"));

        let mut env = Envelope::repoint(
            "n",
            &"ab".repeat(32),
            &"cd".repeat(32),
            BigUint::from(1u32),
            &"aa".repeat(32),
        );
        env.parent_rev = BigUint::from(0u32);
        assert!(encode(&env).unwrap_err().contains("both or neither"));
    }

    #[test]
    fn framing_errors_are_rejected() {
        let good = "oath-publish/1\nop=put\nname=n\nartifact=abababababababababababababababababababababababababababababababab\nparent=-\nparent_rev=0\nauthor=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n";
        assert!(parse(good.as_bytes()).is_ok());

        // missing trailing LF
        assert!(parse(good.trim_end_matches('\n').as_bytes())
            .unwrap_err()
            .contains("end with an LF"));
        // trailing bytes / an extra field
        assert!(parse(format!("{}extra=1\n", good).as_bytes())
            .unwrap_err()
            .contains("7 lines"));
        assert!(parse(format!("{}x", good).as_bytes()).is_err());
        // a blank line at the end is an eighth line, not whitespace to ignore
        assert!(parse(format!("{}\n", good).as_bytes()).is_err());
        // reordered fields
        let reordered = good.replacen("op=put\nname=n\n", "name=n\nop=put\n", 1);
        assert!(parse(reordered.as_bytes()).unwrap_err().contains("must be"));
        // a missing field
        let missing = good.replacen("parent=-\n", "", 1);
        assert!(parse(missing.as_bytes()).is_err());
        // a duplicated field
        let dup = good.replacen("op=put\n", "op=put\nop=put\n", 1);
        assert!(parse(dup.as_bytes()).is_err());
        // op other than put
        let op = good.replacen("op=put", "op=delete", 1);
        assert!(parse(op.as_bytes()).unwrap_err().contains("op must be `put`"));
        // an empty name
        let noname = good.replacen("name=n", "name=", 1);
        assert!(parse(noname.as_bytes()).unwrap_err().contains("non-empty"));
    }

    #[test]
    fn an_injected_lf_presents_as_a_line_count_error() {
        // §8.6.1 says so explicitly: the value rule proper is an ENCODER
        // obligation and is unreachable from the parse side.
        let mut env = Envelope::first("a\nb", &"ab".repeat(32), &"aa".repeat(32));
        let err = encode(&env).unwrap_err();
        assert!(err.contains("U+000A"), "{}", err);
        env.name = "a\rb".into();
        assert!(encode(&env).unwrap_err().contains("U+000D"));
        env.name = "a\u{7f}b".into();
        assert!(encode(&env).unwrap_err().contains("U+007F"));
        env.name = "a\u{1}b".into();
        assert!(encode(&env).unwrap_err().contains("U+0001"));

        // The same octets, if they somehow reached a reader, are eight lines.
        let injected = "oath-publish/1\nop=put\nname=a\nb\nartifact=abababababababababababababababababababababababababababababababab\nparent=-\nparent_rev=0\nauthor=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n";
        let err = parse(injected.as_bytes()).unwrap_err();
        assert!(err.contains("7 lines"), "{}", err);
    }

    #[test]
    fn a_non_ascii_but_printable_character_above_7f_is_allowed() {
        // The rule is "below 0x20 or equal to 0x7F" — U+0085 (NEL) is above it,
        // so the letter of §8.6.1 permits it even though it is a control
        // character in Unicode. Recorded in DIVERGENCES.md.
        let env = Envelope::first("a\u{85}b", &"ab".repeat(32), &"aa".repeat(32));
        let octets = encode(&env).expect("permitted by the letter of §8.6.1");
        assert_eq!(parse(&octets).unwrap(), env);
    }

    // -- §8.6.3 base64 --------------------------------------------------------

    #[test]
    fn base64_round_trips_in_the_pinned_dialect() {
        for n in 0..12usize {
            let bytes: Vec<u8> = (0..n).map(|i| (i * 37 + 11) as u8).collect();
            let s = b64_encode(&bytes);
            assert_eq!(s.len() % 4, 0, "padding is required");
            assert_eq!(b64_decode(&s).unwrap(), bytes);
            assert_eq!(envelope_octets(&s).unwrap(), bytes);
        }
        assert_eq!(b64_encode(b""), "");
        assert_eq!(b64_encode(&[0xffu8, 0xfe]), "//4=");
    }

    #[test]
    fn the_pinned_dialect_refuses_every_other_spelling() {
        let octets = encode(&Envelope::first("n", &"ab".repeat(32), &"aa".repeat(32))).unwrap();
        let good = b64_encode(&octets);
        assert!(envelope_octets(&good).is_ok());

        // leading / interior / trailing whitespace
        for bad in [
            format!(" {}", good),
            format!("{} ", good),
            format!("{}\n", good),
            good.replacen("b2F0", "b2F 0", 1),
        ] {
            assert!(envelope_octets(&bad).is_err(), "whitespace must be refused: {:?}", bad);
        }
        // unpadded
        assert!(envelope_octets(good.trim_end_matches('=')).is_err());
        // URL-safe substitutions
        assert!(envelope_octets(&b64_encode(&[0xffu8, 0xff, 0xff]).replace('+', "-")).is_err());
        assert!(envelope_octets(&b64_encode(&[0xfbu8, 0xff, 0xff]).replace('/', "_")).is_err());
        // a non-canonical spelling that decodes to the same octets
        assert_eq!(b64_decode("AQ==").unwrap(), vec![1u8]);
        assert_eq!(b64_decode("AR==").unwrap(), vec![1u8]);
        assert!(
            envelope_octets("AR==").is_err(),
            "two stored spellings of one byte string must not both be canonical"
        );
        assert!(envelope_octets("AQ==").is_ok());
    }

    // -- §8.6.4 verification --------------------------------------------------

    /// The honest publication: an envelope, its octets, and an entry carrying
    /// all three publication members.
    fn honest() -> (Envelope, Vec<u8>, Entry) {
        let seed = seed32();
        let author = hex_lower(&ed25519::public_key(&seed));
        let env = Envelope::repoint(
            "double",
            &"55".repeat(32),
            &"66".repeat(32),
            BigUint::from(7u32),
            &author,
        );
        let (octets, sig) = sign_envelope(&seed, &env).unwrap();
        let e = Entry {
            seq: 0,
            author: author.clone(),
            name: "double".into(),
            kind: "func".into(),
            status: "accepted".into(),
            hash: "55".repeat(32),
            prev: "66".repeat(32),
            guarantee: "tested (200 cases per property)".into(),
            termination: "nonrecursive".into(),
            envelope_b64: b64_encode(&octets),
            author_pubkey: author,
            author_sig: hex_lower(&sig),
            name_transition: "applied".into(),
            ..Entry::default()
        };
        (env, octets, e)
    }

    #[test]
    fn an_honest_publication_verifies() {
        let (env, _, e) = honest();
        assert_eq!(verify_entry_publication(&e).unwrap(), Some(env));
        // and the entry line itself is canonical
        let line = journal::encode(&e);
        assert_eq!(journal::parse(&line).unwrap(), e);
    }

    #[test]
    fn no_publication_fields_impose_no_obligation() {
        let mut e = honest().2;
        e.envelope_b64.clear();
        e.author_pubkey.clear();
        e.author_sig.clear();
        assert_eq!(verify_entry_publication(&e).unwrap(), None);
    }

    #[test]
    fn any_one_field_alone_attests_to_nothing() {
        let (_, _, base) = honest();
        for drop in ["envelope_b64", "author_pubkey", "author_sig"] {
            let mut e = base.clone();
            match drop {
                "envelope_b64" => e.envelope_b64.clear(),
                "author_pubkey" => e.author_pubkey.clear(),
                _ => e.author_sig.clear(),
            }
            let err = verify_entry_publication(&e).unwrap_err();
            assert!(err.contains("all of"), "dropping {}: {}", drop, err);
        }
    }

    #[test]
    fn every_envelope_field_is_bound_by_the_signature() {
        let (_, octets, base) = honest();
        let text = String::from_utf8(octets).unwrap();
        // The six tamperings the fixtures pin, plus the format tag.
        let tampers = [
            ("op", text.replacen("op=put", "op=put ", 1)),
            ("name", text.replacen("name=double", "name=other", 1)),
            ("artifact", text.replacen(&"55".repeat(32), &"99".repeat(32), 1)),
            ("parent", text.replacen(&"66".repeat(32), &"77".repeat(32), 1)),
            ("parent_rev", text.replacen("parent_rev=7", "parent_rev=8", 1)),
            (
                "author",
                text.replacen(&base.author_pubkey, &"dd".repeat(32), 1),
            ),
            ("format", text.replacen("oath-publish/1", "oath-publish/2", 1)),
        ];
        for (field, tampered) in tampers {
            assert_ne!(tampered, text, "the {} tamper must change the octets", field);
            let mut e = base.clone();
            e.envelope_b64 = b64_encode(tampered.as_bytes());
            assert!(
                verify_entry_publication(&e).is_err(),
                "tampering with {} must fail verification",
                field
            );
        }
    }

    #[test]
    fn the_envelope_author_must_be_the_entrys_author_pubkey() {
        let seed = seed32();
        let author = hex_lower(&ed25519::public_key(&seed));
        let env = Envelope::first("n", &"55".repeat(32), &author);
        let (octets, sig) = sign_envelope(&seed, &env).unwrap();
        let mut e = Entry {
            name: "n".into(),
            status: "accepted".into(),
            hash: "55".repeat(32),
            envelope_b64: b64_encode(&octets),
            author_pubkey: "dd".repeat(32),
            author_sig: hex_lower(&sig),
            ..Entry::default()
        };
        let err = verify_entry_publication(&e).unwrap_err();
        assert!(err.contains("§8.6.4.3"), "{}", err);
        e.author_pubkey = author;
        assert!(verify_entry_publication(&e).is_ok());
    }

    #[test]
    fn clause_five_is_a_hard_failure() {
        let (_, _, base) = honest();
        // the entry names something else
        let mut e = base.clone();
        e.name = "other".into();
        assert!(verify_entry_publication(&e).unwrap_err().contains("§8.6.4.5"));
        // the entry's hash is not the signed artifact
        let mut e = base.clone();
        e.hash = "99".repeat(32);
        assert!(verify_entry_publication(&e).unwrap_err().contains("§8.6.4.5"));
        // the entry's prev is not the signed parent
        let mut e = base.clone();
        e.prev = "77".repeat(32);
        assert!(verify_entry_publication(&e).unwrap_err().contains("§8.6.4.5"));
        // an ABSENT prev means `-`, and disagrees with a real parent
        let mut e = base.clone();
        e.prev.clear();
        let err = verify_entry_publication(&e).unwrap_err();
        assert!(err.contains("§8.6.4.5"), "{}", err);
    }

    #[test]
    fn a_same_hash_republication_still_carries_its_real_parent() {
        // §8.2 (as amended): `prev` is the hash the name pointed at BEFORE the
        // entry — ALWAYS, including when it already pointed at the same hash. If
        // an unchanged binding collapsed `prev` to absent, the envelope would
        // name the real parent while the entry said `-`, and §8.6.4(5) would have
        // to fail a correctly signed, correctly accepted publication.
        let seed = seed32();
        let author = hex_lower(&ed25519::public_key(&seed));
        let hash = "55".repeat(32);
        let env = Envelope::repoint("n", &hash, &hash, BigUint::from(3u32), &author);
        let (octets, sig) = sign_envelope(&seed, &env).unwrap();
        let e = Entry {
            name: "n".into(),
            kind: "func".into(),
            status: "accepted".into(),
            hash: hash.clone(),
            prev: hash.clone(),
            envelope_b64: b64_encode(&octets),
            author_pubkey: author,
            author_sig: hex_lower(&sig),
            name_transition: "unchanged".into(),
            ..Entry::default()
        };
        assert_eq!(verify_entry_publication(&e).unwrap(), Some(env));
        assert_eq!(e.effective_transition(), journal::Transition::Unchanged);
    }

    #[test]
    fn the_signature_is_over_the_decoded_octets_not_the_base64_text() {
        let seed = seed32();
        let author = hex_lower(&ed25519::public_key(&seed));
        let env = Envelope::first("n", &"55".repeat(32), &author);
        let (octets, _) = sign_envelope(&seed, &env).unwrap();
        let member = b64_encode(&octets);
        // Signing the base64 TEXT produces a signature that must NOT be accepted.
        let wrong = ed25519::sign(&seed, member.as_bytes());
        let e = Entry {
            name: "n".into(),
            status: "accepted".into(),
            hash: "55".repeat(32),
            envelope_b64: member,
            author_pubkey: author,
            author_sig: hex_lower(&wrong),
            ..Entry::default()
        };
        assert!(verify_entry_publication(&e)
            .unwrap_err()
            .contains("does not verify"));
    }

    // -- §8.6.4 store-side checks --------------------------------------------

    #[test]
    fn the_store_checks_the_authenticated_principal_not_the_named_author() {
        let author_seed = seed32();
        let mut other_seed = seed32();
        other_seed[0] ^= 0xff;
        let author = hex_lower(&ed25519::public_key(&author_seed));
        let env = Envelope::repoint(
            "n",
            &"55".repeat(32),
            &"66".repeat(32),
            BigUint::from(4u32),
            &author,
        );
        let (octets, sig) = sign_envelope(&author_seed, &env).unwrap();
        let state = NameState {
            parent: Some(&"66".repeat(32)),
            rev: BigUint::from(4u32),
        };

        // The author's own submission is accepted.
        assert!(check_before_move(
            &octets,
            &sig,
            &ed25519::public_key(&author_seed),
            &"55".repeat(32),
            &state
        )
        .is_ok());

        // A relay holding a perfectly valid statement made by someone ELSE is
        // not making that statement. Verifying against the envelope's own
        // `author` would have accepted this.
        let err = check_before_move(
            &octets,
            &sig,
            &ed25519::public_key(&other_seed),
            &"55".repeat(32),
            &state,
        )
        .unwrap_err();
        assert!(err.contains("authenticated principal"), "{}", err);
    }

    #[test]
    fn the_store_recomputes_the_artifact_hash_and_compares_the_name_state() {
        let seed = seed32();
        let pk = ed25519::public_key(&seed);
        let author = hex_lower(&pk);
        let env = Envelope::repoint(
            "n",
            &"55".repeat(32),
            &"66".repeat(32),
            BigUint::from(4u32),
            &author,
        );
        let (octets, sig) = sign_envelope(&seed, &env).unwrap();

        // The store's own elaboration disagrees with the signed artifact.
        let state = NameState {
            parent: Some(&"66".repeat(32)),
            rev: BigUint::from(4u32),
        };
        assert!(
            check_before_move(&octets, &sig, &pk, &"99".repeat(32), &state)
                .unwrap_err()
                .contains("submitted content")
        );

        // A replay: the parent is right but the revision has moved on (the A→B→A
        // case §8.6.2 describes).
        let moved = NameState {
            parent: Some(&"66".repeat(32)),
            rev: BigUint::from(6u32),
        };
        assert!(
            check_before_move(&octets, &sig, &pk, &"55".repeat(32), &moved)
                .unwrap_err()
                .contains("current revision")
        );

        // A stale parent.
        let elsewhere = NameState {
            parent: Some(&"77".repeat(32)),
            rev: BigUint::from(4u32),
        };
        assert!(
            check_before_move(&octets, &sig, &pk, &"55".repeat(32), &elsewhere)
                .unwrap_err()
                .contains("current value")
        );

        // A first publication against a name that already exists.
        let first = Envelope::first("n", &"55".repeat(32), &author);
        let (foctets, fsig) = sign_envelope(&seed, &first).unwrap();
        assert!(check_before_move(&foctets, &fsig, &pk, &"55".repeat(32), &state).is_err());
        let fresh = NameState {
            parent: None,
            rev: BigUint::from(0u32),
        };
        assert!(check_before_move(&foctets, &fsig, &pk, &"55".repeat(32), &fresh).is_ok());
    }

    #[test]
    fn sign_envelope_refuses_to_sign_someone_elses_statement() {
        let seed = seed32();
        let env = Envelope::first("n", &"55".repeat(32), &"dd".repeat(32));
        assert!(sign_envelope(&seed, &env).unwrap_err().contains("but the seed's key is"));
    }

    #[test]
    fn hex_is_lowercase_only() {
        assert_eq!(hex_lower(&[0x0a, 0xff]), "0aff");
        assert_eq!(unhex_lower("0aff"), Some(vec![0x0a, 0xff]));
        assert_eq!(unhex_lower("0AFF"), None, "uppercase is a second spelling");
        assert_eq!(unhex_lower("0af"), None);
        assert_eq!(unhex_lower("0ag0"), None);
    }
}

