// ---------------------------------------------------------------------------
// §10.1 the signed-publication vectors
// ---------------------------------------------------------------------------

/// The conformance surface for §8.6: `fixtures/envelope/vectors.jsonl`.
///
/// This lives in the library rather than in the CLI (where `enctest` lives)
/// because reading the vectors needs a JSON reader, and the same harness has to
/// serve both `cargo test` and conformance check 9. It is still pure computation
/// — it takes the fixture TEXT, never a path — so the wasm surface is unchanged.
///
/// §10.1 carries every octet string as canonical base64 deliberately: a fixture
/// format that presumes the reference language's string-literal syntax is not a
/// cross-kernel fixture.
pub mod vectors {
    use super::*;
    use crate::journal;

    /// One vector's result.
    pub struct Outcome {
        pub kind: String,
        pub label: String,
        pub ok: bool,
        /// Why it failed, or what was checked when it passed.
        pub detail: String,
    }

    /// Check every record in a §10.1 vectors file.
    ///
    ///  * `canonical` — the structured `envelope` MUST encode to `octets_b64`
    ///    byte-for-byte, and those octets MUST parse back to the same envelope;
    ///  * `reject` — `octets_b64` (or `envelope_b64`) MUST be refused;
    ///  * `signature` — the whole path MUST verify, or fail, exactly as `verdict`
    ///    says.
    pub fn check(jsonl: &str) -> Result<Vec<Outcome>, String> {
        let mut out = Vec::new();
        for (n, line) in jsonl.lines().enumerate() {
            if line.trim().is_empty() {
                continue;
            }
            let rec = json(line).map_err(|e| format!("line {}: {}", n + 1, e))?;
            let kind = rec.string("kind").unwrap_or_default().to_string();
            let label = rec.string("label").unwrap_or_default().to_string();
            let result = match kind.as_str() {
                "canonical" => canonical(&rec),
                "reject" => reject(&rec),
                "signature" => signature(&rec),
                other => Err(format!("unknown record kind {:?}", other)),
            };
            out.push(match result {
                Ok(detail) => Outcome {
                    kind,
                    label,
                    ok: true,
                    detail,
                },
                Err(detail) => Outcome {
                    kind,
                    label,
                    ok: false,
                    detail,
                },
            });
        }
        if out.is_empty() {
            return Err("the vectors file contains no records".into());
        }
        Ok(out)
    }

    /// A `canonical` record: these octets are what a signature is computed over,
    /// so one differing byte makes every signature this kernel produces
    /// unverifiable elsewhere — silently, since the signature stays correct.
    fn canonical(rec: &Json) -> Result<String, String> {
        let want = rec.octets("octets_b64")?;
        let env = envelope_from_json(rec.get("envelope").ok_or("record has no `envelope`")?)?;
        let got = encode(&env)?;
        if got != want {
            return Err(format!(
                "octets differ\n    want: {:?}\n    got:  {:?}",
                String::from_utf8_lossy(&want),
                String::from_utf8_lossy(&got)
            ));
        }
        // …and the strict parser must recover exactly the structure that produced
        // them (§8.6.1's re-encode-to-input obligation, from the other side).
        let back = parse(&want)?;
        if back != env {
            return Err(format!("re-parsed envelope differs: {:?} vs {:?}", back, env));
        }
        Ok(format!("{} octets", want.len()))
    }

    /// A `reject` record. Some carry raw `octets_b64`, some carry a stored
    /// `envelope_b64` whose base64 dialect is itself the defect (§8.6.3).
    fn reject(rec: &Json) -> Result<String, String> {
        let reason = rec.string("reason").unwrap_or("").to_string();
        if let Some(member) = rec.string("envelope_b64") {
            return match envelope_octets(member).and_then(|o| parse(&o).map(|_| ())) {
                Err(e) => Ok(format!("refused ({}) — {}", first_clause(&e), reason)),
                Ok(()) => Err(format!("WRONGLY ACCEPTED — {}", reason)),
            };
        }
        let octets = rec.octets("octets_b64")?;
        match parse(&octets) {
            Err(e) => Ok(format!("refused ({}) — {}", first_clause(&e), reason)),
            Ok(_) => Err(format!("WRONGLY ACCEPTED — {}", reason)),
        }
    }

    /// A `signature` record: the whole path. Every optional member present is
    /// checked, because each pins a different link in the chain from a seed to a
    /// journal line.
    fn signature(rec: &Json) -> Result<String, String> {
        let verdict = rec.string("verdict").ok_or("record has no `verdict`")?.to_string();
        let octets = rec.octets("octets_b64")?;
        let pubkey_hex = rec.string("author_pubkey").ok_or("no `author_pubkey`")?;
        let sig_hex = rec.string("author_sig").ok_or("no `author_sig`")?;
        let mut checked: Vec<String> = Vec::new();

        // The verification a third party performs: parse the octets strictly,
        // require the envelope's author to be the key, and verify the signature
        // over THOSE octets (§8.6.4 clauses 2-4).
        let verified = (|| -> Result<(), String> {
            let env = parse(&octets)?;
            if env.author != pubkey_hex {
                return Err(format!(
                    "envelope author {:?} is not author_pubkey {:?}",
                    env.author, pubkey_hex
                ));
            }
            let key = unhex_lower(pubkey_hex).ok_or("author_pubkey is not lowercase hex")?;
            let sig = unhex_lower(sig_hex).ok_or("author_sig is not lowercase hex")?;
            if key.len() != 32 || sig.len() != 64 {
                return Err("author_pubkey must be 32 bytes and author_sig 64".into());
            }
            ed25519::verify(&key, &sig, &octets).map_err(|e| e.to_string())
        })();

        match (verdict.as_str(), &verified) {
            ("accept", Err(e)) => return Err(format!("expected accept, got: {}", e)),
            ("reject", Ok(())) => {
                let what = rec
                    .string("tampered_field")
                    .map(|f| format!("tampered `{}` still verified", f))
                    .unwrap_or_else(|| "expected reject, but it verified".into());
                return Err(format!(
                    "{} — a signed field that still verifies after tampering is not bound by \
                     the signature",
                    what
                ));
            }
            ("accept", Ok(())) => checked.push("signature".into()),
            ("reject", Err(e)) => checked.push(format!("refused ({})", first_clause(e))),
            (other, _) => return Err(format!("unknown verdict {:?}", other)),
        }

        // The structured envelope, when given, must encode to the same octets.
        if let Some(e) = rec.get("envelope") {
            let env = envelope_from_json(e)?;
            if encode(&env)? != octets {
                return Err("the structured `envelope` does not encode to `octets_b64`".into());
            }
            checked.push("structure".into());
        }

        // §8.6.3: `envelope_b64` as STORED must decode to exactly these octets,
        // in the pinned dialect.
        if let Some(member) = rec.string("envelope_b64") {
            if envelope_octets(member)? != octets {
                return Err("`envelope_b64` does not decode to `octets_b64`".into());
            }
            checked.push("envelope_b64".into());
        }

        // §10.1: keys are derived from `seed_b64`, and signing is deterministic
        // (§8.6.4a) — so both the key and the signature must be re-derivable.
        if let Some(s) = rec.string("seed_b64") {
            let raw = b64_decode(s)?;
            if raw.len() != 32 {
                return Err(format!("seed must be 32 bytes, got {}", raw.len()));
            }
            let mut seed = [0u8; 32];
            seed.copy_from_slice(&raw);
            let derived = hex_lower(&ed25519::public_key(&seed));
            if derived != pubkey_hex {
                return Err(format!(
                    "the seed derives key {:?}, not author_pubkey {:?}",
                    derived, pubkey_hex
                ));
            }
            let resigned = hex_lower(&ed25519::sign(&seed, &octets));
            if resigned != sig_hex {
                return Err(format!(
                    "deterministic signing gives {:?}, fixture records {:?}",
                    resigned, sig_hex
                ));
            }
            checked.push("seed→key→signature".into());
        }

        // The journal line, when given: strict §8.2.1 reading, then the full
        // §8.6.4 entry obligation, then the §8.2.2 publication identity.
        if let Some(b64) = rec.string("journal_line_b64") {
            let raw = b64_decode(b64)?;
            let line = std::str::from_utf8(&raw)
                .map_err(|e| format!("journal line is not UTF-8: {}", e))?;
            let entry = journal::parse(line)
                .map_err(|e| format!("journal line is not a canonical entry (§8.2.1): {}", e))?;
            let got = verify_entry_publication(&entry)?
                .ok_or("the journal line carries no publication fields")?;
            if encode(&got)? != octets {
                return Err("the entry's envelope is not these octets".into());
            }
            let digest = journal::entry_digest_of_line(line)?;
            if digest.len() != 64 {
                return Err("the entry digest is not 64 hex characters".into());
            }
            checked.push(format!("journal line (§8.2.1/§8.6.4), digest {}", &digest[..12]));
        }

        Ok(checked.join(", "))
    }

    /// Keep an error message to one line, so a passing vector's `detail` reads as
    /// a reason rather than a paragraph.
    fn first_clause(e: &str) -> String {
        let head = e.split('\n').next().unwrap_or(e);
        match head.char_indices().nth(60) {
            Some((i, _)) => format!("{}…", &head[..i]),
            None => head.to_string(),
        }
    }

    /// Build an [`Envelope`] from a vector's structured `envelope` member.
    ///
    /// `parent_rev` arrives as a JSON number and is read from its TEXT, not
    /// through any machine integer: §8.6.1 makes it unbounded, and a fixture is
    /// entitled to carry a revision no `u64` can hold.
    fn envelope_from_json(v: &Json) -> Result<Envelope, String> {
        let s = |k: &str| -> Result<String, String> {
            v.string(k)
                .map(|s| s.to_string())
                .ok_or_else(|| format!("envelope member {:?} is missing or not a string", k))
        };
        let parent_field = s("parent")?;
        let rev_text = v
            .number("parent_rev")
            .ok_or("envelope member \"parent_rev\" is missing or not a number")?;
        Ok(Envelope {
            op: s("op")?,
            name: s("name")?,
            artifact: s("artifact")?,
            parent: if parent_field == NO_PARENT {
                None
            } else {
                Some(parent_field)
            },
            parent_rev: super::parse_canonical_decimal(rev_text)?,
            author: s("author")?,
        })
    }

    // -- a small permissive JSON reader, for fixtures only -------------------
    //
    // Deliberately NOT the strict reader of §8.2.1: this parses a fixture file,
    // where nothing is byte-significant. The strict reader lives in `journal`
    // and is the one that must refuse a second spelling.

    pub enum Json {
        Str(String),
        Num(String),
        Obj(Vec<(String, Json)>),
    }

    impl Json {
        fn get(&self, key: &str) -> Option<&Json> {
            match self {
                Json::Obj(kv) => kv.iter().find(|(k, _)| k == key).map(|(_, v)| v),
                _ => None,
            }
        }
        fn string(&self, key: &str) -> Option<&str> {
            match self.get(key) {
                Some(Json::Str(s)) => Some(s),
                _ => None,
            }
        }
        fn number(&self, key: &str) -> Option<&str> {
            match self.get(key) {
                Some(Json::Num(n)) => Some(n),
                _ => None,
            }
        }
        /// A base64 member, decoded in the §8.6.3 dialect.
        fn octets(&self, key: &str) -> Result<Vec<u8>, String> {
            let s = self
                .string(key)
                .ok_or_else(|| format!("record member {:?} is missing or not a string", key))?;
            b64_decode(s).map_err(|e| format!("{}: {}", key, e))
        }
    }

    fn json(text: &str) -> Result<Json, String> {
        let mut p = P {
            b: text.as_bytes(),
            i: 0,
        };
        let v = p.value()?;
        p.ws();
        if p.i != p.b.len() {
            return Err(format!("trailing content at byte {}", p.i));
        }
        Ok(v)
    }

    struct P<'a> {
        b: &'a [u8],
        i: usize,
    }

    impl<'a> P<'a> {
        fn ws(&mut self) {
            while matches!(self.b.get(self.i), Some(c) if c.is_ascii_whitespace()) {
                self.i += 1;
            }
        }
        fn value(&mut self) -> Result<Json, String> {
            self.ws();
            match self.b.get(self.i) {
                Some(b'"') => Ok(Json::Str(self.string()?)),
                Some(b'{') => self.object(),
                Some(c) if c.is_ascii_digit() || *c == b'-' => {
                    let start = self.i;
                    self.i += 1;
                    while matches!(self.b.get(self.i), Some(c) if c.is_ascii_digit() || *c == b'.' || *c == b'e' || *c == b'E' || *c == b'+' || *c == b'-')
                    {
                        self.i += 1;
                    }
                    Ok(Json::Num(
                        std::str::from_utf8(&self.b[start..self.i])
                            .map_err(|e| e.to_string())?
                            .to_string(),
                    ))
                }
                Some(c) => Err(format!("unexpected {:?} at byte {}", *c as char, self.i)),
                None => Err("unexpected end of input".into()),
            }
        }
        fn object(&mut self) -> Result<Json, String> {
            self.i += 1; // '{'
            let mut kv = Vec::new();
            self.ws();
            if self.b.get(self.i) == Some(&b'}') {
                self.i += 1;
                return Ok(Json::Obj(kv));
            }
            loop {
                self.ws();
                let k = self.string()?;
                self.ws();
                if self.b.get(self.i) != Some(&b':') {
                    return Err(format!("expected ':' at byte {}", self.i));
                }
                self.i += 1;
                kv.push((k, self.value()?));
                self.ws();
                match self.b.get(self.i) {
                    Some(b',') => self.i += 1,
                    Some(b'}') => {
                        self.i += 1;
                        return Ok(Json::Obj(kv));
                    }
                    _ => return Err(format!("expected ',' or '}}' at byte {}", self.i)),
                }
            }
        }
        fn string(&mut self) -> Result<String, String> {
            if self.b.get(self.i) != Some(&b'"') {
                return Err(format!("expected a string at byte {}", self.i));
            }
            self.i += 1;
            let mut out = String::new();
            loop {
                let c = *self.b.get(self.i).ok_or("unterminated string")?;
                self.i += 1;
                match c {
                    b'"' => return Ok(out),
                    b'\\' => {
                        let e = *self.b.get(self.i).ok_or("truncated escape")?;
                        self.i += 1;
                        match e {
                            b'"' => out.push('"'),
                            b'\\' => out.push('\\'),
                            b'/' => out.push('/'),
                            b'b' => out.push('\u{8}'),
                            b'f' => out.push('\u{c}'),
                            b'n' => out.push('\n'),
                            b'r' => out.push('\r'),
                            b't' => out.push('\t'),
                            b'u' => {
                                let h = std::str::from_utf8(
                                    self.b.get(self.i..self.i + 4).ok_or("truncated \\u")?,
                                )
                                .map_err(|e| e.to_string())?;
                                let cp = u32::from_str_radix(h, 16).map_err(|e| e.to_string())?;
                                self.i += 4;
                                out.push(char::from_u32(cp).unwrap_or('\u{fffd}'));
                            }
                            e => return Err(format!("bad escape \\{}", e as char)),
                        }
                    }
                    _ => {
                        let start = self.i - 1;
                        let len = if c < 0x80 {
                            1
                        } else if c >> 5 == 0b110 {
                            2
                        } else if c >> 4 == 0b1110 {
                            3
                        } else {
                            4
                        };
                        self.i = start + len;
                        out.push_str(
                            std::str::from_utf8(
                                self.b.get(start..self.i).ok_or("truncated UTF-8")?,
                            )
                            .map_err(|e| e.to_string())?,
                        );
                    }
                }
            }
        }
    }
}

