// ---------------------------------------------------------------------------
// §10.1 the signed-publication vectors
// ---------------------------------------------------------------------------

/// The conformance surface for §8.6: `fixtures/envelope/vectors.jsonl`.
///
/// This lives in the library rather than in the CLI (where `enctest` lives)
/// because reading the vectors needs a JSON reader, and the same harness has to
/// serve both `cargo test` and conformance check 9. It is still pure computation
/// — it takes the fixture TEXT, never a path — so the wasm surface is unchanged.
///
/// §10.1 carries every octet string as canonical base64 deliberately: a fixture
/// format that presumes the reference language's string-literal syntax is not a
/// cross-kernel fixture.
pub mod vectors {
    use super::*;
    use crate::journal;

    /// One vector's result.
    pub struct Outcome {
        pub kind: String,
        pub label: String,
        pub ok: bool,
        /// Why it failed, or what was checked when it passed.
        pub detail: String,
    }

    /// Check every record in a §10.1 vectors file.
    ///
    ///  * `canonical` — the structured `envelope` MUST encode to `octets_b64`
    ///    byte-for-byte, and those octets MUST parse back to the same envelope;
    ///  * `reject` — `octets_b64` (or `envelope_b64`) MUST be refused;
    ///  * `signature` — the whole path MUST verify, or fail, exactly as `verdict`
    ///    says.
    pub fn check(jsonl: &str) -> Result<Vec<Outcome>, String> {
        let mut out = Vec::new();
        for (n, line) in jsonl.lines().enumerate() {
            if line.trim().is_empty() {
                continue;
            }
            let rec = json(line).map_err(|e| format!("line {}: {}", n + 1, e))?;
            let kind = rec.string("kind").unwrap_or_default().to_string();
            let label = rec.string("label").unwrap_or_default().to_string();
            let result = match kind.as_str() {
                "canonical" => canonical(&rec),
                "reject" => reject(&rec),
                "signature" => signature(&rec),
                other => Err(format!("unknown record kind {:?}", other)),
            };
            out.push(match result {
                Ok(detail) => Outcome {
                    kind,
                    label,
                    ok: true,
                    detail,
                },
                Err(detail) => Outcome {
                    kind,
                    label,
                    ok: false,
                    detail,
                },
            });
        }
        if out.is_empty() {
            return Err("the vectors file contains no records".into());
        }
        Ok(out)
    }

    /// A `canonical` record: these octets are what a signature is computed over,
    /// so one differing byte makes every signature this kernel produces
    /// unverifiable elsewhere — silently, since the signature stays correct.
    fn canonical(rec: &Json) -> Result<String, String> {
        let want = rec.octets("octets_b64")?;
        let env = envelope_from_json(rec.get("envelope").ok_or("record has no `envelope`")?)?;
        let got = encode(&env)?;
        if got != want {
            return Err(format!(
                "octets differ\n    want: {:?}\n    got:  {:?}",
                String::from_utf8_lossy(&want),
                String::from_utf8_lossy(&got)
            ));
        }
        // …and the strict parser must recover exactly the structure that produced
        // them (§8.6.1's re-encode-to-input obligation, from the other side).
        let back = parse(&want)?;
        if back != env {
            return Err(format!("re-parsed envelope differs: {:?} vs {:?}", back, env));
        }
        Ok(format!("{} octets", want.len()))
    }

    /// A `reject` record. Some carry raw `octets_b64`, some carry a stored
    /// `envelope_b64` whose base64 dialect is itself the defect (§8.6.3).
    fn reject(rec: &Json) -> Result<String, String> {
        let reason = rec.string("reason").unwrap_or("").to_string();
        if let Some(member) = rec.string("envelope_b64") {
            return match envelope_octets(member).and_then(|o| parse(&o).map(|_| ())) {
                Err(e) => Ok(format!("refused ({}) — {}", first_clause(&e), reason)),
                Ok(()) => Err(format!("WRONGLY ACCEPTED — {}", reason)),
            };
        }
        let octets = rec.octets("octets_b64")?;
        match parse(&octets) {
            Err(e) => Ok(format!("refused ({}) — {}", first_clause(&e), reason)),
            Ok(_) => Err(format!("WRONGLY ACCEPTED — {}", reason)),
        }
    }

    /// A `signature` record: the whole path. Every optional member present is
    /// checked, because each pins a different link in the chain from a seed to a
    /// journal line.
    fn signature(rec: &Json) -> Result<String, String> {
        let verdict = rec.string("verdict").ok_or("record has no `verdict`")?.to_string();
        let octets = rec.octets("octets_b64")?;
        let pubkey_hex = rec.string("author_pubkey").ok_or("no `author_pubkey`")?;
        let sig_hex = rec.string("author_sig").ok_or("no `author_sig`")?;
        let mut checked: Vec<String> = Vec::new();

        // The verification a third party performs: parse the octets strictly,
        // require the envelope's author to be the key, and verify the signature
        // over THOSE octets (§8.6.4 clauses 2-4).
        let verified = (|| -> Result<(), String> {
            let env = parse(&octets)?;
            if env.author != pubkey_hex {
                return Err(format!(
                    "envelope author {:?} is not author_pubkey {:?}",
                    env.author, pubkey_hex
                ));
            }
            let key = unhex_lower(pubkey_hex).ok_or("author_pubkey is not lowercase hex")?;
            let sig = unhex_lower(sig_hex).ok_or("author_sig is not lowercase hex")?;
            if key.len() != 32 || sig.len() != 64 {
                return Err("author_pubkey must be 32 bytes and author_sig 64".into());
            }
            ed25519::verify(&key, &sig, &octets).map_err(|e| e.to_string())
        })();

