            if resigned != sig_hex {
                return Err(format!(
                    "deterministic signing gives {:?}, fixture records {:?}",
                    resigned, sig_hex
                ));
            }
            checked.push("seed→key→signature".into());
        }

        // The journal line, when given: strict §8.2.1 reading, then the full
        // §8.6.4 entry obligation, then the §8.2.2 publication identity.
        if let Some(b64) = rec.string("journal_line_b64") {
            let raw = b64_decode(b64)?;
            let line = std::str::from_utf8(&raw)
                .map_err(|e| format!("journal line is not UTF-8: {}", e))?;
