    /// `parent_rev` arrives as a JSON number and is read from its TEXT, not
    /// through any machine integer: §8.6.1 makes it unbounded, and a fixture is
    /// entitled to carry a revision no `u64` can hold.
    fn envelope_from_json(v: &Json) -> Result<Envelope, String> {
        let s = |k: &str| -> Result<String, String> {
            v.string(k)
                .map(|s| s.to_string())
                .ok_or_else(|| format!("envelope member {:?} is missing or not a string", k))
        };
