#[cfg(test)]
mod tests {
    use super::*;
    use crate::journal;

    /// The §10.1 vectors, embedded rather than read from disk so the test module
    /// stays as host-free as the library (the `campaign` fixtures do the same).
    const VECTORS: &str = include_str!(concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../fixtures/envelope/vectors.jsonl"
    ));

    #[test]
    fn every_vector_behaves_as_the_fixture_says() {
        let outcomes = vectors::check(VECTORS).expect("the vectors file parses");
        let mut kinds = std::collections::BTreeMap::new();
        for o in &outcomes {
            *kinds.entry(o.kind.clone()).or_insert(0usize) += 1;
            assert!(o.ok, "[{}] {}: {}", o.kind, o.label, o.detail);
        }
        // All three record kinds must actually be exercised — a harness that
        // silently skipped `signature` records would pass while checking nothing.
        for kind in ["canonical", "reject", "signature"] {
            assert!(
                kinds.get(kind).copied().unwrap_or(0) > 0,
                "no {} records were checked",
                kind
            );
        }
        assert_eq!(outcomes.len(), 21, "the pinned vector set");
    }

    #[test]
    fn the_harness_fails_loudly_when_a_vector_is_wrong() {
        // A canonical record whose octets are one byte off must FAIL, otherwise
        // check 9 proves nothing. `parent_rev=0` -> `parent_rev=1` in the octets
        // only, leaving the structure alone.
        let env = Envelope::first("double", &"11".repeat(32), &"aa".repeat(32));
        let mut octets = encode(&env).unwrap();
        let at = octets
            .windows(13)
            .position(|w| w == b"parent_rev=0\n")
            .unwrap();
        octets[at + 11] = b'1';
        let rec = format!(
            r#"{{"kind":"canonical","label":"broken","envelope":{{"op":"put","name":"double","artifact":"{}","parent":"-","parent_rev":0}},"octets_b64":"{}"}}"#,
            "11".repeat(32),
            b64_encode(&octets)
        );
        let outcomes = vectors::check(&rec).unwrap();
        assert!(!outcomes[0].ok, "a one-byte difference must be caught");

        // A `reject` record that this kernel accepts must FAIL too.
        let good = b64_encode(&encode(&env).unwrap());
        let rec = format!(
            r#"{{"kind":"reject","label":"actually fine","reason":"none","octets_b64":"{}"}}"#,
            good
        );
        let outcomes = vectors::check(&rec).unwrap();
        assert!(!outcomes[0].ok, "an accepted `reject` vector must be caught");
        assert!(outcomes[0].detail.contains("WRONGLY ACCEPTED"));

        // And a `signature` record whose verdict is `reject` but which verifies.
        let seed: [u8; 32] = (1u8..=32).collect::<Vec<u8>>().try_into().unwrap();
        let author = hex_lower(&ed25519::public_key(&seed));
        let env = Envelope::first("n", &"55".repeat(32), &author);
        let (octets, sig) = sign_envelope(&seed, &env).unwrap();
        let rec = format!(
            r#"{{"kind":"signature","label":"should have failed","verdict":"reject","tampered_field":"nothing","octets_b64":"{}","author_pubkey":"{}","author_sig":"{}"}}"#,
            b64_encode(&octets),
            author,
            hex_lower(&sig)
        );
        let outcomes = vectors::check(&rec).unwrap();
        assert!(!outcomes[0].ok);
        assert!(outcomes[0].detail.contains("not bound by the signature"));
    }

