/// Conformance check 9 (SPEC §10.1, MANIFEST criterion 8): run every
/// signed-publication vector in `fixtures/envelope/vectors.jsonl`.
///
/// Needs no solver, so it belongs in both conformance modes. Each record prints
/// one line and the command exits nonzero if any record misbehaved — including
/// a `reject` record this kernel accepted, which is the failure direction a
/// harness that only checked the happy path would miss.
fn cmd_envtest(path: &str) -> i32 {
    let text = match fs::read_to_string(path) {
        Ok(t) => t,
        Err(e) => {
            eprintln!("envtest: cannot read {}: {}", path, e);
            return 1;
        }
    };
    let outcomes = match oathrs::publish::vectors::check(&text) {
        Ok(o) => o,
        Err(e) => {
            eprintln!("envtest: {}", e);
            return 1;
        }
    };
    let mut ok = true;
    let mut counts: std::collections::BTreeMap<&str, usize> = std::collections::BTreeMap::new();
    for o in &outcomes {
        if o.ok {
            *counts.entry(match o.kind.as_str() {
                "canonical" => "canonical",
                "reject" => "reject",
                _ => "signature",
            })
            .or_insert(0) += 1;
            println!("envtest {} {}: ok — {}", o.kind, o.label, o.detail);
        } else {
            ok = false;
            eprintln!("envtest {} {}: FAIL — {}", o.kind, o.label, o.detail);
        }
    }
    if ok {
        println!(
            "envtest: {} vectors ({} canonical, {} reject, {} signature)",
            outcomes.len(),
            counts.get("canonical").copied().unwrap_or(0),
            counts.get("reject").copied().unwrap_or(0),
            counts.get("signature").copied().unwrap_or(0),
        );
        0
    } else {
        1
    }
}

