/// A KNOWN SPEC DEFECT, pinned as a test so it is visible rather than
/// folklore. See DIVERGENCES.md — the headline finding of #87.
///
/// §8.6.2's legacy derivation says an entry "whose `prev` equals its `hash`
/// was a no-op (`unchanged`)". But the entries the derivation exists for were
/// written under the UNAMENDED §8.2, which omitted `prev` "when the name was
/// new **or already pointed at the same hash**". So in a genuinely legacy
/// journal a same-hash re-publication has `prev` ABSENT, the `prev == hash`
/// test can never fire on it, and the entry is counted as `applied`.
///
/// The revision therefore inflates by one per legacy no-op — which defeats
/// exactly the property §8.6.2 introduced `unchanged` to protect: "If it
/// advanced the revision, a harmless no-op would invalidate every envelope
/// prepared against a state that never changed."
///
/// This kernel implements the LETTER of §8.6.2, so it agrees with any other
/// kernel reading the same text. The assertion below records the wrong answer
/// on purpose; when §8.6.2 is amended (the derivation has to become a fold
/// over the log, since a single entry cannot distinguish "new name" from
/// "same hash"), this test should flip to 1.
#[test]
fn legacy_same_hash_republication_inflates_the_revision_spec_defect() {
    let a = "aa".repeat(32);
    // Two entries as the pre-amendment §8.2 would have written them: the
    // first publication, then a re-put of the identical definition. Both omit
    // `prev` — the second because the name "already pointed at the same hash".
    let legacy = vec![
        ent("n", "func", "accepted", &a, "", ""),
        ent("n", "func", "accepted", &a, "", ""),
    ];
    assert_eq!(
        name_revision(&legacy, "n"),
        BigUint::from(2u32),
        "the letter of §8.6.2 counts a legacy no-op as a state change"
    );
    // The name never left `a`: there was one state, not two.
    assert_eq!(resolve(&legacy, "n"), Some(a.clone()));

    // Written under the AMENDED §8.2, the same history counts correctly,
    // because `prev` is now present and equal to `hash`.
    let amended = vec![
        ent("n", "func", "accepted", &a, "", ""),
        ent("n", "func", "accepted", &a, &a, ""),
    ];
    assert_eq!(name_revision(&amended, "n"), BigUint::from(1u32));
}

